    /**
 * --------------------------------------------------------------------
 * LAZY LOADING
 * --------------------------------------------------------------------
 */

    @-webkit-keyframes lazyLoader {

        0%,
        100% {
            transform: translateX(-50%);
        }

        50% {
            transform: translateX(100%);
        }
    }

    @keyframes lazyLoader {

        0%,
        100% {
            transform: translateX(-50%);
        }

        50% {
            transform: translateX(100%);
        }
    }

    img.lazyload[data-sizes=auto] {
        width: 100%;
        /* this is needed to help LazySizes calculate the correct size */
    }

