            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
        }

        .article-comment__date {
            margin-bottom: 12px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * BLOG
 * --------------------------------------------------------------------
 */

    .shopify-section__article {
        max-width: 980px;
    }

    .blog-sidebar__item {
        margin-bottom: 45px;
    }

    .blog-sidebar__item--products,
    .blog-sidebar__item--newsletter {
        margin-bottom: 50px;
        /* we add a bit of additional spacing to those two are the content is not made of text that brings its own spacing due to line-height */
    }

    .blog-sidebar__item:first-child:not(.blog-sidebar__item--newsletter) {
        margin-top: -0.435em;
    }

    .blog-sidebar__block-title {
        margin-bottom: 20px;
    }

    @media screen and (min-width: 1000px) {

        /* From tablet and up the sidebar is on the right */
        .blog-container {
            display: flex;
            align-items: flex-start;
            justify-content: center;
        }

        .shopify-section__blog-posts,
        .shopify-section__article {
            /* IE11 has issue with the shorthand form */
            flex-grow: 1;
            flex-shrink: 0;
            flex-basis: 0;
        }

        .blog-sidebar {
            width: 300px;
            margin-left: 60px;
        }
    }

    @media screen and (min-width: 641px) and (max-width: 999px) {
        .blog-sidebar {
            width: 350px;
            margin-left: auto;
            margin-right: auto;
        }
    }

    @media screen and (min-width: 1280px) {
        .blog-sidebar {
            width: 350px;
            margin-left: 70px;
        }
    }

    /* Newsletter */
    .blog-sidebar__item--newsletter {
        padding: 30px 20px 30px 20px;
        border-radius: 3px;
        text-align: center;
    }

    .blog-sidebar__item--newsletter .heading {
        color: inherit;
    }

    @media screen and (max-width: 640px) {

        /* On mobile it goes to the edge */
        .blog-sidebar__item--newsletter {
            border-radius: 0;
            margin-left: calc(-1 * var(--mobile-container-gutter));
            margin-right: calc(-1 * var(--mobile-container-gutter));
        }
    }

    /* Featured blog posts */
    .blog-sidebar__post-list {
        list-style: none;
    }

    .blog-sidebar__post-item {
        display: flex;
        align-items: flex-start;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    .features--animate-zoom .blog-sidebar__post-item:hover .blog-sidebar__post-image {
        transform: scale(1.1);
    }

    .blog-sidebar__post-item:hover .blog-sidebar__post-title {
        color: var(--accent-color);
    }

    .blog-sidebar__post-item+.blog-sidebar__post-item {
        margin-top: 30px;
    }

    .blog-sidebar__post-image-wrapper {
        position: relative;
        display: block;
        flex-shrink: 0;
        width: 100px;
        margin-right: 20px;
    }

    .blog-sidebar__post-image,
    .blog-sidebar__post-placeholder {
        min-height: 80px;
        transition: transform 0.65s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }

    .blog-sidebar__post-image-overflow {
        overflow: hidden;
        border-radius: 3px;
    }

    .blog-sidebar__post-title {
        position: relative;
        display: block;
        display: -webkit-box;
        margin-top: 2px;
        line-height: 1.55;
        overflow: hidden;
        text-overflow: ellipsis;
        -webkit-line-clamp: 2;
        /* autoprefixer: ignore next */
        -webkit-box-orient: vertical;
    }

    .blog-sidebar__post-meta {
        margin-top: 4px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
    }

    .blog-sidebar__post-meta-item:not(:last-child)::after {
        display: inline-block;
        content: "";
        width: 5px;
        height: 5px;
        margin: 0 10px;
        border-radius: 100%;
        background: rgba(var(--text-color-rgb), 0.4);
        vertical-align: middle;
    }

    .blog-sidebar__post-list--ranked {
        counter-reset: post-ranking 0;
    }

    .blog-sidebar__post-list--ranked .blog-sidebar__post-image-wrapper::before {
        position: absolute;
        content: counter(post-ranking);
        top: calc(50% - 16px);
        left: -16px;
        border: 2px solid var(--background);
        height: 32px;
        width: 32px;
        line-height: 28px;
        /* 32px minus 4px of border */
        text-align: center;
        border-radius: 100%;
        background: var(--accent-color);
        color: var(--secondary-background);
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        counter-increment: post-ranking;
        z-index: 1;
    }

    /* Products */
    .blog-sidebar__item--products .product-item {
        width: 100%;
    }

    .blog-sidebar__item--products .product-item__image-wrapper {
        width: 75px !important;
    }

    .blog-sidebar__item--products .product-item__price-list>.price {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
    }

    @media screen and (max-width: 640px) {

        /* For the sidebar the products display slightly differently as they do not goes edge to edge */
        .blog-sidebar__item--products .product-list--horizontal {
            border: 1px solid var(--border-color);
            border-radius: 3px;
        }
    }

    /* Linklists */
    .blog-sidebar__linklist {
        list-style: none;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    .blog-sidebar__link-item {
        padding: 14px 0;
        border-bottom: 1px solid var(--form-border-color);
        line-height: 1.5;
    }

    .blog-sidebar__link-item:first-child {
        padding-top: 5px;
    }

    .blog-sidebar__link-item:last-child {
        border-bottom: none;
        padding-bottom: 0;
    }

    .blog-sidebar__link-item>a {
        display: block;
    }

    .button {
        position: relative;
        display: inline-block;
        padding: 0 30px;
        line-height: 48px;
        border-radius: 2px;
        text-align: center;
        font-weight: var(--text-font-bolder-weight);
        font-size: var(--base-text-font-size);
        cursor: pointer;
        transition: background 0.25s ease-in-out, color 0.25s ease-in-out, box-shadow 0.25s ease-in-out;
        border-radius: 8px;
    }

    .button[disabled] {
        cursor: not-allowed;
    }

    .button--extra-small {
        padding: 0 15px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        line-height: 34px;
    }

    .button--small {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        line-height: 42px;
    }

    .button--large {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
        line-height: 55px;
    }

    .button--extra-large {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 18px));
        line-height: 60px;
    }

    .button--primary {
        background: var(--primary-button-background);
        color: var(--primary-button-text-color);
    }

    .button--primary:hover {
        background: rgba(var(--primary-button-background-rgb), 0.8);
    }

    .button--secondary {
        background: var(--secondary-button-background);
        color: var(--secondary-button-text-color);
    }

    .button--secondary:hover {
        background: rgba(var(--secondary-button-background-rgb), 0.8);
    }

    .button--ternary {
        color: var(--accent-color);
        box-shadow: 0 0 0 1px var(--border-color) inset;
        /* use box-shadow instead of border to not create additional space */
    }

    .button--ternary:hover {
        background: rgba(var(--border-color-rgb), 0.5);
        color: var(--text-color);
    }

    .button--transparent {
        color: var(--text-color);
        box-shadow: 0 0 0 1px var(--border-color) inset;
        /* use box-shadow instead of border to not create additional space */
    }

    .button--transparent:hover {
        background: var(--primary-button-background);
        color: var(--primary-button-text-color);
        box-shadow: 0 0 0 1px var(--primary-button-background) inset;
    }

    /* The color scheme is a bit hacky here, but basically this button is only used for the sold out button, so we re-use the
   sold out label to create some consistence */
    .button--disabled {
        background: var(--product-sold-out-color);
        box-shadow: 0 0 0 1px var(--product-sold-out-color) inset;
        /* use box-shadow instead of border to not create additional space */
        color: var(--secondary-background);
    }

    .button--full {
        width: 100%;
    }

    .button--min-width {
        min-width: 200px;
    }

    .button--floating {
        transition: box-shadow 0.2s ease-in-out;
    }

    .button--floating:hover {
        box-shadow: 0 2px 2px 2px rgba(0, 0, 0, 0.06);
    }

    /**
 * --------------------------------------------------------------------
 * BUTTON WRAPPER
 * --------------------------------------------------------------------
 */

    .button-wrapper {
        text-align: center;
    }

    /**
 * --------------------------------------------------------------------
 * BUTTON STACK
 * --------------------------------------------------------------------
 */

    .button-stack {
        display: flex;
        flex-direction: column;
    }

    .button-stack>.button+.button {
        margin-top: 10px;
    }

    /**
 * --------------------------------------------------------------------
 * BUTTON GROUP
 * --------------------------------------------------------------------
 */

    .button-group {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        margin: -5px;
    }

    .button-group>* {
        margin: 5px;
    }

    .button-group--fit>* {
        flex: 1 0 0;
        padding-left: 15px;
        padding-right: 15px;
    }

    .button-group--loose {
        margin: -10px;
    }

    .button-group--loose>* {
        margin: 10px;
    }

    /**
 * --------------------------------------------------------------------
 * Standard card
 * --------------------------------------------------------------------
 */

    .card {
        position: relative;
        margin-bottom: 18px;
        background: var(--secondary-background);
        border-top: 1px solid var(--border-color);
        border-bottom: 1px solid var(--border-color);
        border-radius: 14px !important;
    }

    .card__header {
        position: relative;
        padding: 20px 20px 0 20px;
    }

    .card__header--flex {
        display: flex;
        align-items: center;
        justify-content: space-between;
    }

    .card__title {
        margin-bottom: 0;
    }

    .card__subtitle {
        margin-bottom: 14px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
    }

    .card__subtitle:first-child {
        margin-top: -0.435em;
    }

    .card__title--small {
        margin-bottom: 10px;
        margin-top: -2px;
        /* Those kind of micro-adjustments rules are not really beautiful, but it's here to satisfy need of pixel perfect... */
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 20px));
    }

    .card__section,
    .card__collapsible-button {
        position: relative;
        padding: 20px;
    }

    .card__collapsible-button {
        display: flex;
        align-items: center;
        justify-content: space-between;
        text-align: left;
        width: 100%;
        cursor: pointer;
    }

    .card__collapsible-button .plus-button {
        margin-left: 10px;
        color: var(--heading-color);
    }

    .card__section+.card__section::before {
        position: absolute;
        display: block;
        content: "";
        width: calc(100% - var(--mobile-container-gutter));
        top: 0;
        right: 0;
        height: 1px;
        background: var(--border-color);
    }

    .card__section--no-padding {
        padding: 0 !important;
    }

    .card__collapsible {
        height: 0;
        overflow: hidden;
        transition: 0.3s ease-in-out;
    }

    .card__collapsible-content {
        padding: 0 20px 20px 20px;
    }

    .card__separator {
        width: calc(100% + var(--mobile-container-gutter));
        margin: 20px 0;
        border: none;
        border-top: 1px solid var(--border-color);
    }

    .card__navigation {
        display: flex;
        justify-content: space-between;
        margin-bottom: 12px;
        margin-top: -3px;
        /* Yeah, designers like making things simple complicated :D */
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    .card__navigation-breadcrumb svg {
        margin-right: 12px;
        width: 8px;
        height: 12px;
        vertical-align: -1px;
    }

    .card__linklist {
        list-style: none;
    }

    .card__linklist-item {
        display: block;
        padding: 2px 0;
        text-align: left;
    }

    @media screen and (max-width: 640px) {
        .card {
            border-radius: 0;
            /* cards expand full-width on mobile */
        }

        .card__section--flex .button {
            margin-top: 20px;
            width: 100%;
        }
    }

    @media screen and (max-width: 999px) {
        .card--collapsed {
            margin-top: -18px !important;
            border-top: none !important;
            box-shadow: 0 -1px var(--secondary-background);
            /* allows to hide the border of the previous card */
        }

        .card--collapsed .card__header,
        .card--collapsed .card__section {
            padding-top: 0;
        }
    }

    @media screen and (min-width: 641px) and (max-width: 999px) {
        .card--collapsed {
            margin-top: -30px !important;
            border-radius: 0 0 3px 3px;
        }
    }

    @media screen and (min-width: 641px) {
        .card {
            margin-bottom: 30px;
            border-radius: 3px;
            border: 1px solid var(--border-color);
        }

        .card__header {
            padding: 30px 30px 0 30px;
        }

        .card__section,
        .card__collapsible-button {
            padding: 30px;
        }

        .card__section+.card__section::before {
            width: 100%;
        }

        .card__section--flex {
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .card__subtitle {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        }

        .card__collapsible-content {
            padding: 0 30px 30px 30px;
        }

        .card__separator {
            width: 100%;
            margin: 24px 0;
        }

        .card__header--tight {
            padding-top: 20px;
        }

        .card__section--tight {
            padding: 20px 25px;
        }

        .card__section--tight .card__separator {
            margin: 20px 0;
        }

        .card__navigation {
            margin-bottom: 15px;
        }
    }

    @media screen and (min-width: 1000px) {
        .card--sticky {
            position: -webkit-sticky;
            position: sticky;
            top: 0;
            margin-bottom: 0;
        }

        @supports (--css: variables) {
            .card--sticky {
                top: calc((var(--header-height) + 30px) * 0);
                top: calc((var(--header-height) + 30px) * var(--header-is-sticky, 0));
            }
        }
    }

    .card__section .rte .button:last-child {
        margin-bottom: 15px;
    }

    /**
 * --------------------------------------------------------------------
 * Mini-cart
 * --------------------------------------------------------------------
 */

    .mini-cart {
        position: absolute;
        width: 100vw;
        height: 100vh;
        left: 0;
        top: 100%;
        max-height: 0;
        /* This is needed to fix a bug on iOS, DO NOT REMOVE */
        background: var(--secondary-background);
        color: var(--text-color);
        z-index: 1;
        visibility: hidden;
        opacity: 0;
        transform: scale(0.9);
        transition: opacity 0.25s ease-in-out, transform 0.25s ease-in-out, visibility 0.25s ease-in-out, max-height 0s linear 0.25s;
        will-change: transform;
    }

    .mini-cart[aria-hidden=false] {
        visibility: visible;
        opacity: 1;
        transform: scale(1);
        transition: opacity 0.4s cubic-bezier(0, 1, 0.4, 1), transform 0.4s cubic-bezier(0.18, 1.25, 0.4, 1), visibility 0.4s linear;
    }

    .mini-cart .icon--nav-triangle-borderless {
        position: absolute;
        width: 18px;
        height: 8px;
        right: 6px;
        bottom: 100%;
        z-index: 2;
        filter: drop-shadow(0 -2px 2px rgba(0, 0, 0, 0.12));
    }

    .mini-cart__alert-wrapper {
        padding-top: 20px;
    }

    .mini-cart .alert {
        margin-bottom: 0;
        flex-shrink: 0;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    .mini-cart__content:not(.mini-cart__content--empty)>* {
        padding-left: 20px;
        padding-right: 20px;
    }

    .mini-cart__content--empty {
        padding: 20px 25px 25px 25px;
    }

    .mini-cart__empty-state {
        padding: 70px 0 60px 0;
        text-align: center;
    }

    .mini-cart__empty-state svg {
        margin-bottom: 10px;
    }

    .mini-cart__line-item-list {
        overflow: auto;
        -webkit-overflow-scrolling: touch;
        -ms-scroll-chaining: none;
        overscroll-behavior: none;
    }

    .mini-cart__line-item {
        display: flex;
        align-items: flex-start;
        padding: 20px 0;
    }

    .mini-cart__line-item+.mini-cart__line-item {
        border-top: 1px solid var(--border-color);
    }

    .mini-cart__image-wrapper {
        min-width: 80px;
        width: 80px;
        margin-right: 20px;
    }

    .mini-cart__product-info {
        margin-bottom: 12px;
    }

    .mini-cart__product-vendor,
    .mini-cart__property-list,
    .mini-cart__plan-allocation {
        display: block;
        margin-bottom: 7px;
        line-height: 1.55;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
    }

    .mini-cart__product-vendor {
        text-transform: uppercase;
    }

    .mini-cart__product-title {
        display: block;
        margin-bottom: 4px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        line-height: 1.5;
    }

    .mini-cart__property-list {
        list-style: none;
        line-height: 1.5;
        margin: 6px 0;
    }

    .mini-cart__price-list>.price {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        font-weight: var(--text-font-bolder-weight);
    }

    .mini-cart__price-info {
        margin-top: -2px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
    }

    .mini-cart__discount-list {
        list-style: none;
        margin-top: 2px;
    }

    .mini-cart__discount {
        display: inline-block;
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        background: rgba(var(--product-on-sale-accent-rgb), 0.08);
        color: var(--product-on-sale-accent);
        border-radius: 2px;
        padding: 0 11px;
    }

    .mini-cart__discount svg {
        margin-right: 6px;
        vertical-align: text-bottom;
    }

    .mini-cart__discount+.mini-cart__discount {
        margin-top: 5px;
    }

    .mini-cart__quantity-remove {
        display: inline-block;
        margin-left: 10px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        line-height: 1;
    }

    .mini-cart__recap {
        padding: 15px 20px 20px 20px;
        border-top: 1px solid var(--border-color);
    }

    .mini-cart__recap-price-line {
        display: flex;
        align-items: center;
        justify-content: space-between;
        color: var(--heading-color);
        font-weight: var(--text-font-bolder-weight);
    }

    .mini-cart__recap-price-line--highlight {
        color: var(--product-on-sale-accent);
    }

    .mini-cart__recap-price-line+.mini-cart__recap-price-line {
        margin-top: 4px;
    }

    .mini-cart__amount-saved {
        color: var(--product-on-sale-accent);
        font-weight: var(--text-font-bolder-weight);
    }

    .mini-cart__button-container {
        margin-top: 16px;
    }

    @media screen and (max-width: 640px) {
        .mini-cart .icon--nav-triangle-borderless {
            right: 24px;
        }

        .mini-cart__content {
            display: flex;
            flex-direction: column;
        }

        .mini-cart__inner,
        .mini-cart__content--empty {
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            height: calc(100% - 20px);
            /* We remove a bit of space to fix the double click issue on iOS */
        }

        .mini-cart__inner {
            display: flex;
            flex-direction: column;
            height: 100%;
        }

        .mini-cart__recap {
            flex: 1;
        }
    }

    @media screen and (min-width: 641px) {
        .mini-cart {
            left: auto;
            right: 0;
            top: calc(100% + 14px);
            max-height: none;
            width: 470px;
            height: auto;
            border-radius: 3px;
            box-shadow: 0 1px 5px 2px rgba(0, 0, 0, 0.1);
        }

        .mini-cart__content>* {
            padding-left: 25px;
            padding-right: 25px;
        }

        .mini-cart__content--empty {
            padding-bottom: 25px;
        }

        .mini-cart__line-item-list {
            max-height: 300px;
        }

        .mini-cart__item-wrapper {
            display: flex;
            flex-grow: 1;
            align-items: flex-start;
            justify-content: space-between;
        }

        .mini-cart__quantity-remove {
            display: block;
            width: -webkit-max-content;
            width: -moz-max-content;
            width: max-content;
            margin: 10px auto 0 auto;
        }

        .mini-cart__product-info {
            margin: 0 20px 0 0;
        }

        .mini-cart__recap {
            padding: 15px 25px 25px 25px;
        }
    }

    @media screen and (min-height: 700px) and (min-width: 641px) {
        .mini-cart__line-item-list {
            max-height: 330px;
        }
    }

    @media screen and (min-width: 1280px) {
        .mini-cart .icon--nav-triangle-borderless {
            right: 58px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * Main cart general layout
 *
 * On desktop, the recap is moved to the right, while the main content
 * has a restricted width
 * --------------------------------------------------------------------
 */

    .cart-recap__secure-payment-list {
        max-width: 300px;
        margin: -4px auto !important;
    }

    @media screen and (max-width: 999px) {
        .cart-wrapper {
            min-height: 0 !important;
        }
    }

    @media screen and (min-width: 1000px) {
        .cart-wrapper {
            max-width: 1480px;
            margin-left: auto;
            margin-right: auto;
        }

        .cart-wrapper__inner {
            position: relative;
        }

        .cart-wrapper__inner-inner {
            width: calc(100% - 380px);
        }

        .cart-recap {
            position: absolute;
            right: var(--desktop-container-gutter);
            top: 0;
            width: 350px;
            height: 100%;
        }

        .cart-recap__scroller {
            position: -webkit-sticky;
            position: sticky;
            top: 0;
        }

        @supports (--css: variables) {
            .cart-recap__scroller {
                top: calc(var(--header-height) + 30px);
            }
        }
    }

    @media screen and (min-width: 1280px) {
        .cart-wrapper__inner-inner {
            width: calc(100% - 430px);
        }

        .cart-recap {
            width: 400px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * Gift wrap
 * --------------------------------------------------------------------
 */

    .gift-wrap {
        padding: 20px 10px 20px 20px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    .gift-wrap__left {
        display: flex;
        align-items: center;
        margin-bottom: 18px;
    }

    .gift-wrap__icon svg {
        display: block;
        margin-top: -4px;
        margin-right: 25px;
        width: 24px;
        height: 24px;
    }

    .gift-wrap__text>span:first-child {
        margin-right: 10px;
    }

    @media screen and (min-width: 641px) {
        .gift-wrap {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 10px 10px 10px 30px;
        }

        .gift-wrap__left {
            margin-bottom: 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * Estimate shipping (this is quite similar to the gift wrap code, and
 * may be good to find a good block abstraction to make the code re-usable
 * --------------------------------------------------------------------
 */

    .estimate-shipping {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    .estimate-shipping__toggle {
        display: flex;
        align-items: center;
        padding: 20px;
        width: 100%;
        color: var(--heading-color);
        font-weight: var(--text-font-bolder-weight);
    }

    .estimate-shipping__icon svg {
        display: block;
        margin-right: 25px;
        width: 24px;
        height: 24px;
    }

    .estimate-shipping__arrow {
        margin-left: auto;
    }

    .estimate-shipping__arrow svg {
        width: 12px;
        height: 8px;
        transition: transform 0.2s ease-in-out;
    }

    .estimate-shipping__toggle[aria-expanded=true] .estimate-shipping__arrow svg {
        transform: rotateZ(180deg);
    }

    .estimate-shipping__collapsible .shipping-estimator {
        padding: 0 20px 20px 20px;
    }

    @media screen and (min-width: 641px) {
        .estimate-shipping__toggle {
            padding: 20px 30px;
        }

        .estimate-shipping__collapsible .shipping-estimator {
            padding-right: 30px;
            padding-left: 30px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * Cart recap
 * --------------------------------------------------------------------
 */

    .cart-recap__price-line {
        display: flex;
        justify-content: space-between;
        margin-bottom: 4px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 15px));
        font-weight: var(--text-font-bolder-weight);
        color: var(--heading-color);
    }

    .cart-recap__price-line+.cart-recap__price-line {
        margin-top: 4px;
    }

    .cart-recap__price-line--highlight {
        color: var(--product-on-sale-accent);
    }

    .cart-recap__amount-saved {
        color: var(--product-on-sale-accent);
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 15px));
    }

    .cart-recap__note {
        margin-top: 14px;
        border-top: 1px solid var(--border-color);
        border-bottom: 1px solid var(--border-color);
    }

    .cart-recap__note-inner {
        padding-bottom: 20px;
    }

    .cart-recap__note-button {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 10px 0;
        width: 100%;
    }

    .cart-recap__note-button svg {
        width: 12px;
        height: 8px;
        transition: transform 0.2s ease-in-out;
    }

    .cart-recap__note-button[aria-expanded=true] svg {
        transform: rotateZ(180deg);
    }

    .cart-recap__note-edit {
        margin-right: 14px;
        color: var(--accent-color);
        opacity: 0;
        transition: opacity 0.2s ease-in-out;
    }

    .cart-recap__note-edit.is-visible {
        opacity: 1;
    }

    .cart-recap__notices {
        margin: 24px 0;
    }

    .cart-recap__secure-payment-title {
        margin-bottom: 10px;
        text-align: center;
        font-weight: var(--text-font-bolder-weight);
    }

    .cart-recap__secure-payment-title svg {
        margin-right: 8px;
        vertical-align: text-top;
    }

    @media screen and (min-width: 641px) {
        .cart-recap__price-line {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 18px));
        }

        .cart-recap__amount-saved {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
        }

        .cart-recap__note {
            margin-top: 20px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * MAIN COLLECTION
 * --------------------------------------------------------------------
 */

    .collection__image-wrapper {
        position: relative;
        height: 180px;
        margin-bottom: -1px;
        z-index: 1;
        overflow: hidden;
    }

    .collection__image-wrapper--small {
        height: 140px;
    }

    .collection__image-wrapper--large {
        height: 230px;
    }

    .collection__image-wrapper--preserve-ratio {
        height: auto !important;
        /* Height depends on the ratio of the original image */
    }

    .collection__image-wrapper+.card {
        border-top-left-radius: 0;
        border-top-right-radius: 0;
    }

    .collection__image {
        height: 100%;
        background-size: cover;
        background-position: center;
    }

    .collection__title {
        margin-bottom: 5px;
    }

    .collection__meta {
        margin-bottom: 12px;
    }

    .collection__description {
        margin-top: 20px;
    }

    .collection__brand-logo-wrapper {
        margin-right: 20px;
        padding: 10px;
        width: 70px;
        height: 70px;
        border: 1px solid var(--border-color);
        border-radius: 3px;
    }

    .collection__brand-logo-image {
        height: 100%;
        width: 100%;
        background-size: contain;
        background-repeat: no-repeat;
        background-position: center;
    }

    .collection__products-count {
        margin-bottom: 18px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
    }

    .collection__toolbar {
        position: relative;
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-top: 22px;
        padding: 0 var(--mobile-container-gutter);
        box-shadow: 0 1px var(--border-color), 0 -1px var(--border-color);
        background: var(--secondary-background);
        z-index: 3;
    }

    .collection__toolbar-item {
        display: flex;
        align-items: center;
        height: 48px;
    }

    .collection__toolbar-item--filter svg {
        margin-right: 12px;
        width: 19px;
        height: 20px;
    }

    .collection__layout-label {
        margin-right: 20px;
    }

    .collection__layout-button {
        opacity: 0.7;
        transition: all 0.2s ease-in-out;
    }

    .collection__layout-button:last-child {
        margin-left: 15px;
    }

    .collection__layout-button:hover {
        opacity: 1;
    }

    .collection__layout-button.is-selected {
        opacity: 1;
        color: var(--heading-color);
    }

    .collection__layout-button svg {
        display: block;
        width: 18px;
        height: 18px;
    }

    /* Adjustment when the expanded description is enabled */
    .collection__header .expandable-content--expandable {
        margin-bottom: -22px;
    }

    /* Brand variant */
    .collection__header--brand .collection__meta {
        display: flex;
        align-items: center;
    }

    .collection__header--brand .collection__description {
        margin-top: 0;
    }

    @media screen and (max-width: 999px) {
        .collection__toolbar {
            position: -webkit-sticky;
            position: sticky;
            top: calc(var(--header-height) * 0);
            top: calc(var(--header-height) * var(--header-is-sticky, 0));
        }
    }

    @media screen and (min-width: 641px) {
        .collection__image-wrapper {
            height: 230px;
            border-radius: 3px 3px 0 0;
        }

        .collection__image-wrapper--small {
            height: 200px;
        }

        .collection__image-wrapper--large {
            height: 310px;
        }

        .collection__brand-logo-wrapper {
            width: 90px;
            height: 90px;
            margin-right: 30px;
        }

        .collection__products-count {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        }

        .collection__toolbar {
            padding: 0 30px;
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        }

        .collection__toolbar--bordered {
            margin-top: 30px;
            box-shadow: 0 1px var(--border-color), 0 -1px var(--border-color);
        }

        .card__header--tight+.collection__toolbar--bordered {
            margin-top: 25px;
        }

        .collection__toolbar-item {
            height: 58px;
        }

        .collection__toolbar-item .value-picker-button {
            margin-left: 4px;
        }
    }

    @media screen and (max-width: 640px) {
        .collection__toolbar-item--count+.collection__toolbar-item--layout {
            margin-left: auto;
        }
    }

    @media screen and (min-width: 1000px) {
        .collection__toolbar:not(.collection__toolbar--bordered) {
            margin-top: -12px;
            box-shadow: 0 1px var(--border-color);
        }

        .collection__brand-logo-wrapper {
            width: 110px;
            height: 110px;
            flex: none;
        }

        /* Brand variation */
        .collection__header--brand {
            display: flex;
            align-items: flex-start;
        }

        .collection__header--brand .collection__meta {
            display: block;
        }
    }

    @media screen and (min-width: 1280px) {
        .collection__title {
            margin-bottom: 12px;
        }

        .collection__description {
            margin-top: 10px;
        }

        .collection__showing-count,
        .collection__toolbar-item--sort {
            margin-right: 45px;
        }

        .collection__toolbar-item--sort {
            margin-left: auto;
        }

        /* Brand variation */
        .collection__header--brand .collection__meta {
            margin-bottom: 0;
        }
    }

    @media screen and (min-width: 1440px) {

        .collection__showing-count,
        .collection__toolbar-item--sort {
            margin-right: 80px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * MAIN COLLECTION (FILTER BAR)
 * --------------------------------------------------------------------
 */

    .collection__filter-group-list--ordered {
        display: flex;
        flex-direction: column;
    }

    .collection__filter-group {
        padding: 13px 20px 14px 20px;
        border-bottom: 1px solid var(--border-color);
    }

    .collection__filter-group-name {
        display: flex;
        width: 100%;
        justify-content: space-between;
        align-items: center;
        text-align: left;
    }

    .collection__filter-group-name svg {
        width: 12px;
        height: 8px;
        margin-left: 10px;
        transition: transform 0.25s ease-in-out;
    }

    .collection__filter-group-name[aria-expanded=true] svg {
        transform: rotateZ(180deg);
    }

    .collection__filter-collapsible {
        height: 0;
        overflow: hidden;
        visibility: hidden;
        transition: 0.2s ease-in-out;
    }

    .collection__filter-collapsible[aria-hidden=false] {
        visibility: visible;
    }

    .collection__filter-item-active {
        display: block;
        margin-top: -5px;
        color: var(--accent-color);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
    }

    /* Linklist */
    .collection__filter-linklist {
        list-style: none;
        padding: 4px 0 8px 0;
    }

    .collection__filter-link {
        display: block;
        width: 100%;
        padding: 3px 0 4px 0;
        text-align: left;
    }

    .collection__filter-link svg {
        width: 12px;
        height: 8px;
        margin-left: 8px;
        transition: transform 0.25s ease-in-out;
    }

    .collection__filter-link[aria-expanded=true] svg {
        transform: rotateZ(180deg);
    }

    .collection__filter-link.is-active {
        font-weight: var(--text-font-bolder-weight);
        color: var(--accent-color);
    }

    .collection__filter-linklist .collection__filter-linklist {
        padding: 0 0 0 10px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    /* Colors */
    .collection__filter-color-list {
        padding: 7px 0 5px 6px;
    }

    /* Checkbox */
    .collection__filter-checkbox-list {
        list-style: none;
    }

    .collection__filter-collapsible .collection__filter-checkbox-list {
        padding: 8px 0 7px 10px;
        /* When embedded into a collapsible it get more padding */
    }

    .collection__filter-checkbox {
        display: flex;
        align-items: center;
        padding: 2px 0 3px 0;
    }

    .collection__filter-checkbox label {
        margin-left: 4px;
        /* This is micro-alignment to respect the design due to the usage of flexbox here */
        line-height: 1.5;
    }

    /* Active filters */

    .collection__filter-icon--active {
        position: relative;
    }

    .collection__filter-icon--active::after {
        content: "";
        position: absolute;
        top: 3px;
        left: 13px;
        width: 8px;
        height: 8px;
        border-radius: 100%;
        background: var(--accent-color);
    }

    .collection__active-filters {
        margin: -5px 0 16px 0;
    }

    .collection__active-filters:empty {
        display: none;
    }

    .collection__active-filter-item {
        display: flex;
        width: 100%;
        padding: 4px 0;
        align-items: center;
        line-height: 1.5;
        font-weight: var(--text-font-bolder-weight);
        color: var(--accent-color);
    }

    .collection__active-filter-cross {
        position: relative;
        display: inline-block;
        flex-shrink: 0;
        margin-right: 12px;
        background: var(--accent-color);
        color: var(--secondary-background);
        height: 20px;
        width: 20px;
        border-radius: 3px;
        box-shadow: 0 1px rgba(var(--border-color-rgb), 0.4);
    }

    .collection__active-filter-cross svg {
        position: absolute;
        top: 6px;
        left: 6px;
        width: 8px;
        height: 8px;
        stroke-width: 2px;
        stroke: white;
    }

    .collection__clear-filter {
        margin: 13px 0 9px 0;
    }

    @media screen and (min-width: 1000px) {
        .collection__filter-group {
            padding: 6px 0;
            border-bottom: 0;
        }

        .collection__filter-group-name {
            justify-content: flex-start;
        }

        /* Linklist */
        .collection__filter-linklist {
            padding: 0 0 9px 0;
        }

        .collection__filter-linklist .collection__filter-linklist {
            padding-left: 15px;
        }

        .collection__filter-link {
            padding: 2px 0;
        }

        /* Color */
        .collection__filter-color-list {
            padding: 12px 0 10px 0;
        }

        /* Checkbox */
        .collection__filter-collapsible .collection__filter-checkbox-list {
            padding-bottom: 12px;
        }

        .collection__filter-group:last-child .collection__filter-checkbox-list {
            padding-bottom: 0;
            /* Last one must have its padding removed */
        }

        .collection__filter-checkbox {
            padding: 0;
        }

        .collection__filter-checkbox .checkbox-wrapper {
            margin: 8px 0;
        }
    }

    @media screen and (min-width: 1280px) {
        .collection__sidebar {
            flex-basis: 290px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * MAIN COLLECTION (FILTER BAR MOBILE)
 * --------------------------------------------------------------------
 */

    .collection__mobile-filters-recap {
        background: var(--background);
        border-bottom: 1px solid var(--border-color);
    }

    .collection__mobile-active-filters {
        margin: -5px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
    }

    .collection__mobile-active-filter-item {
        padding: 4px 12px;
        background: var(--accent-color);
        border-radius: 3px;
        box-shadow: 0 1px rgba(var(--accent-color-rgb), 0.15);
        color: var(--secondary-background);
        font-weight: var(--text-font-bolder-weight);
    }

    .collection__mobile-active-filter-item,
    .collection__mobile-active-clear {
        margin: 5px;
    }

    .collection__mobile-active-filter-cross {
        margin-right: 7px;
    }

    .collection__mobile-active-filter-cross svg {
        width: 7px;
        height: 7px;
        stroke: currentColor;
        stroke-width: 3px;
    }

    .collection__mobile-active-clear {
        position: relative;
        margin-left: 15px;
    }

    .collection__mobile-active-clear::after {
        content: "";
        position: absolute;
        left: 0;
        bottom: 3px;
        width: 100%;
        height: 1px;
        background: currentColor;
    }

    .collection__mobile-active-filters-results {
        display: block;
        margin-top: 25px;
        margin-bottom: -5px;
    }

    /**
 * --------------------------------------------------------------------
 * COLLECTION FILTER DRAWER (MOBILE)
 * --------------------------------------------------------------------
 */

    .collection-drawer {
        display: flex;
        flex-direction: column;
        height: 100%;
    }

    .collection-drawer__header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        flex: 1 0 auto;
        max-height: 64px;
        padding: 15px 15px 15px 25px;
        border-bottom: 1px solid var(--border-color);
        z-index: 1;
    }

    .collection-drawer__header>div {
        display: flex;
        align-items: center;
    }

    .collection-drawer__close {
        margin-right: 16px;
        color: var(--heading-color);
    }

    .collection-drawer__close svg {
        display: block;
        width: 19px;
        height: 19px;
        margin-top: -1px;
    }

    .collection-drawer__title {
        margin-bottom: 0;
    }

    .collection-drawer__inner {
        flex: 1 1 auto;
        overflow: auto;
        -webkit-overflow-scrolling: touch;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 15px));
    }

    .collection-drawer__section-title {
        margin: 0;
        padding: 4px 15px;
        text-transform: uppercase;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
        font-weight: var(--text-font-bolder-weight);
        background: var(--background);
        border-bottom: 1px solid var(--border-color);
    }

    .collection-drawer__footer {
        padding: 15px;
        box-shadow: 0 -2px 2px rgba(var(--border-color-rgb), 0.65);
    }

    .collection-drawer__footer .button {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    /**
 * --------------------------------------------------------------------
 * PRODUCT LIST
 * --------------------------------------------------------------------
 */

    .product-list {
        position: relative;
        display: flex;
        flex-wrap: wrap;
        overflow: hidden;
        width: 100%;
        border-top: 1px solid var(--border-color);
        border-bottom: 1px solid var(--border-color);
        z-index: 1;
        /* This is needed to create a new stacking context to improve performance on iOS */
    }

    .product-list .flickity-viewport {
        border-radius: 3px;
    }

    .product-list--scrollable {
        flex-wrap: nowrap;
    }

    .product-list--collection::before {
        display: none;
    }

    /* This allows to push the content in case when the product item has a quick form button (like on cart page) */
    .product-item--vertical,
    .product-item--vertical .product-item__info {
        display: flex;
        flex-direction: column;
    }

    .product-item--vertical .product-item__info {
        justify-content: space-between;
        flex: 1 0 auto;
    }

    .product-list__column {
        width: 100%;
    }

    @media screen and (max-width: 640px) {

        .product-list--scrollable::before,
        .product-list--scrollable::after {
            content: "";
            flex: 0 0 var(--mobile-container-gutter);
        }

        .product-list--scrollable .product-item {
            width: 62%;
        }

        .product-list--collage {
            border-width: 1px 0;
        }

        .product-list--collection .product-item--vertical {
            width: 50%;
        }
    }

    @media screen and (min-width: 641px) and (max-width: 999px) {

        .product-list--scrollable::before,
        .product-list--scrollable::after {
            content: "";
            flex: 0 0 var(--desktop-container-gutter);
        }

        .product-list--scrollable .product-item {
            width: 36%;
        }
    }

    @media screen and (min-width: 641px) {
        .product-list {
            background: none;
            border-radius: 14px;
            border: none;
        }

        /* This needs to be done instead of applying a border to the product-list to fix a z-index issue with the product labels */
        .product-list--collage::before {
            position: absolute;
            content: "";
            width: 100%;
            height: calc(100% + 0px);
            /* This solves an issue on Safari, where 100% does not always work - likely a pixel rounding issue - */
            border: 1px solid var(--border-color);
            z-index: 1;
            pointer-events: none;
            border-radius: 3px;
        }

        .product-list__column {
            display: flex;
            flex-direction: column;
            flex-wrap: nowrap;
            flex: 0 0 33.333333%;
        }

        .product-list__column>.product-item {
            flex: 1 0 auto;
        }

        .product-list__column--highlight .product-item__title {
            font-size: 1rem;
        }

        @supports (display: grid) {
            .product-list--collage {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(295px, 1fr));
            }

            .product-list__column {
                display: grid;
                grid-auto-rows: 1fr;
            }

            .product-list__column--shrink {
                grid-template-rows: minmax(50%, -webkit-min-content);
                grid-template-rows: minmax(50%, min-content);
            }
        }
    }

    @media screen and (max-width: 999px) {
        .product-list--scrollable {
            overflow: visible;
            border: none;
            background: transparent;
        }

        .product-list--scrollable .product-item {
            border: 1px solid var(--border-color);
        }

        .product-list--scrollable .product-item+.product-item {
            border-left: none;
        }

        .product-list--collection {
            border: none;
        }
    }

    @media screen and (min-width: 1000px) {

        /* This needs to be done instead of applying a border to the product-list to fix a z-index issue with the product labels */
        .product-list::before {
            position: absolute;
            content: "";
            width: 100%;
            height: calc(100% + 0px);
            /* This solves an issue on Safari, where 100% does not always work - likely a pixel rounding issue - */

            z-index: 1;
            pointer-events: none;
            border-radius: 3px;
        }

        .product-list--scrollable::after {
            content: "flickity";
            display: none;
        }

        .product-list--scrollable .product-item {
            min-height: 100%;
        }

        .product-list--stackable {
            flex-wrap: wrap;
        }

        .product-list__column {
            flex-basis: 25%;
        }
    }

    @media screen and (min-width: 1440px) {
        @supports (display: grid) {
            .product-list--collage {
                grid-template-columns: repeat(2, 1fr 1.05fr);
            }
        }
    }

    /**
 * --------------------------------------------------------------------
 * FEATURED COLLECTION (HOME PAGE)
 * --------------------------------------------------------------------
 */

    .featured-collection {
        padding-top: 25px;
        background-repeat: no-repeat;
        background-position: bottom 0 left -15px;
        background-size: 500px auto;
    }

    .featured-collection__header {
        padding: 0 var(--mobile-container-gutter) 40px var(--mobile-container-gutter);
    }

    .featured-collection__title {
        margin-bottom: 8px;
        color: inherit;
    }

    .featured-collection__cta {
        margin-top: 8px;
    }

    .featured-collection__image-wrapper {
        margin-top: 25px;
    }

    .featured-collection .product-list {
        margin-bottom: 20px;
        border-radius: 2px;
    }

    .featured-collection .product-item {
        border: none;
        border-right: 1px solid var(--border-color);
    }

    .featured-collection .product-item::after {
        display: none;
    }

    .featured-collection .product-item:last-child {
        border-right: 0;
    }

    @media screen and (max-width: 640px) {

        .featured-collection,
        .featured-collection__header {
            background-image: none !important;
        }
    }

    @media screen and (min-width: 641px) and (max-width: 999px) {
        .featured-collection {
            margin: 0 calc(-1 * var(--desktop-container-gutter));
            background-image: none !important;
        }

        .featured-collection__header {
            padding-left: var(--desktop-container-gutter);
            padding-right: var(--desktop-container-gutter);
            background-repeat: no-repeat;
            background-position: bottom 0 right -15px;
            background-size: 430px auto;
        }

        .featured-collection__image-wrapper {
            max-width: 400px;
            margin-left: auto;
            margin-right: auto;
        }

        .featured-collection .product-list {
            margin-bottom: var(--desktop-container-gutter);
        }
    }

    @media screen and (min-width: 1000px) {
        .featured-collection {
            display: table;
            /* using Flexbox here didn't work well, so let's use old school and reliable stuff */
            table-layout: fixed;
            width: 100%;
            padding: 6px 6px 6px 0;
            border-radius: 14px;
        }

        .featured-collection__header,
        .featured-collection__content {
            display: table-cell;
            vertical-align: top;
        }

        .featured-collection__header {
            width: 455px;
            padding: 20px 30px;
            background-image: none !important;
        }

        .featured-collection .product-list {
            margin-bottom: 0;
        }

        .featured-collection .product-list::before {
            display: none;
        }

        /* This code is absolutely ugly and hacky, but due to rounding errors on Chrome, sometimes everything is shifted by 1px,
     and designer couldn't tolerate it. I've found this hack which basically adds a box-shadow to "cover" artificially
     the border of last element in the list. No better fix were found so far */
        .featured-collection .flickity-viewport::after {
            content: "";
            position: absolute;
            height: 100%;
            width: 1px;
            background: var(--secondary-background);
            right: 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * COLLECTION ITEM (round style)
 * --------------------------------------------------------------------
 */

    .collection-item {
        display: inline-block;
        width: 24vw;
        margin: 0 14px;
        vertical-align: top;
        white-space: normal;
    }

    .collection-item:first-child {
        margin-left: var(--mobile-container-gutter);
    }

    .collection-item:last-child {
        margin-right: var(--mobile-container-gutter);
    }

    .collection-item__image-wrapper {
        margin-bottom: 15px;
        overflow: hidden;
    }

    .collection-item__image-wrapper--rounded {
        /* adding a stacking context (position: relative; z-index: 0;) is necessary due to a bug in Safari. More info here: https://bugs.webkit.org/show_bug.cgi?id=98538 */
        position: relative;
        z-index: 0;
        overflow: hidden;
        border-radius: 100%;
    }

    .collection-item__image-wrapper img {
        -o-object-fit: cover;
        object-fit: cover;
        -o-object-position: center;
        object-position: center;
        transform: scale(1.01);
        /* The 1.01 is necessary to avoid some rounding issues on Chrome */
        font-family: "object-fit: cover; object-position: center;";
        /* IE11 polyfill */
        transition: opacity 0.2s ease-in-out, transform 0.95s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }

    .collection-item__title {
        display: block;
        line-height: 1.4;
        text-align: center;
        transition: color 0.2s ease-in-out;
    }

    .collection-item__title svg {
        display: none;
    }

    @media screen and (min-width: 641px) and (max-width: 999px) {
        .collection-item {
            width: 190px;
        }

        .collection-item:first-child {
            margin-left: var(--desktop-container-gutter);
        }

        .collection-item:last-child {
            margin-right: var(--desktop-container-gutter);
        }
    }

    @media screen and (min-width: 641px) {
        .collection-item__title {
            transform: translateX(14px);
            transition: transform 0.35s cubic-bezier(0.645, 0.045, 0.355, 1);
        }

        .collection-item__title svg {
            /*
    Note: for some strange reasons, on Safari (even last version), if we use a transform it cause a delay of up to 1 second on heavy home page before the
    animation starts. I couldn't find any explanation, but maybe the nested transforms (on both the link and SVG) does not work correctly on Safari. As a
    consequence, I've used a animation on right property (which is much slower but should be ok on this small piece of content)
    */
            position: relative;
            display: inline-block;
            height: 14px;
            width: 14px;
            vertical-align: -2px;
            margin-left: 8px;
            right: -5px;
            opacity: 0;
            transition: all 0.35s cubic-bezier(0.645, 0.045, 0.355, 1);
        }
    }

    @media screen and (min-width: 1000px) {
        .collection-list {
            margin: 30px -14px 0 -14px;
            white-space: nowrap;
            overflow: hidden;
        }

        .collection-list::after {
            display: none;
            content: "flickity";
            /* enable Flickity slideshow */
        }

        .collection-item {
            width: 20%;
            margin: 0 !important;
            padding: 0 14px;
        }

        .collection-list .flickity-prev-next-button {
            top: calc(50% - 25px - 12px - 0.5em);
            /* 12px is the margin bottom below the image and 0.5em is half a line of text */
        }

        .collection-list .flickity-prev-next-button.previous {
            left: -10px;
        }

        .collection-list .flickity-prev-next-button.next {
            right: -10px;
        }
    }

    @media screen and (min-width: 1280px) {
        .collection-item {
            width: 16.6666667%;
        }
    }

    @media (-moz-touch-enabled: 0),
    (hover: hover) {
        .collection-item:hover .collection-item__title {
            color: var(--accent-color);
        }

        .features--animate-zoom .collection-item:hover img {
            transform: scale(1.07);
        }

        .collection-item:hover .collection-item__title {
            transform: translateX(0);
        }

        .collection-item:hover .collection-item__title svg {
            opacity: 1;
            right: 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * COLLECTION ITEM (block style)
 * --------------------------------------------------------------------
 */

    /* General */
    .collection-list__section {
        margin-bottom: 40px;
    }

    @media screen and (min-width: 641px) {
        .collection-list__section {
            margin-bottom: 60px;
        }
    }

    .collection-block-item {
        display: block;
        position: relative;
        border-radius: 3px;
        overflow: hidden;
    }

    .collection-block-item--overlay::before {
        content: "";
        position: absolute;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.2);
        z-index: 1;
    }

    .collection-block-item__image {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-size: cover;
        background-position: center;
        transition: transform 8s linear, opacity 0.3s ease-in-out !important;
    }

    .collection-block-item__title {
        position: absolute;
        top: 50%;
        left: 50%;
        width: 100%;
        padding: 0 20px;
        transform: translate(-50%, -50%);
        text-align: center;
        color: #ffffff;
        z-index: 1;
        text-shadow: 1px 2px 4px rgba(0, 0, 0, 0.2);
    }

    @media (-moz-touch-enabled: 0),
    (hover: hover) {
        .features--animate-zoom .collection-block-item:hover .collection-block-item__image {
            transform: scale(1.4);
        }
    }

    /**
 * --------------------------------------------------------------------
 * Custom content section (this one is a bit a "fit-all" section, so it
 * was hard to make it very generic)
 * --------------------------------------------------------------------
 */

    .custom-content--centered {
        text-align: center;
    }

    .custom-content--right {
        text-align: right;
    }

    /* Small exception for the standalone product, that is not within a grid, so it must have borders on all edges */
    .custom-content--product .product-item::after {
        box-shadow: 1px 0 var(--border-color), -1px 0 var(--border-color), 0 1px var(--border-color), 0 -1px var(--border-color);
    }

    /**
 * --------------------------------------------------------------------
 * FIELD
 * --------------------------------------------------------------------
 */

    .form__field {
        display: block;
        padding: 12px 12px;
        border-radius: 8px;
        border: 1px solid var(--form-border-color);
        width: 100%;
        line-height: normal;
        height: 48px;
        color: var(--heading-color);
        background: var(--input-background);
        -webkit-appearance: none;
        resize: none;
        font-size: 1rem;
        font-size: max(1rem, 16px);
        /* for modern browser ; setting a min value of 16px is required for accessibility */
        box-shadow: 0 1px rgba(var(--border-color-rgb), 0.25) inset;
        transition: border-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out, color 0.2s ease-in-out;
    }

    .form__field::-moz-placeholder {
        color: var(--text-color);
    }

    .form__field:-ms-input-placeholder {
        color: var(--text-color);
    }

    .form__field::placeholder {
        color: var(--text-color);
    }

    .form__field:focus {
        border-color: var(--accent-color);
        box-shadow: 0 0 0 1px var(--accent-color);
        color: var(--heading-color);
        outline: none;
    }

    .form__field--small {
        height: 44px;
    }

    .form__field--large {
        height: 60px;
        padding: 20px 18px;
    }

    .form__field--textarea {
        height: auto;
        line-height: inherit;
        min-height: 48px;
        padding-top: 6px;
        padding-bottom: 6px;
    }

    .form__field--borderless {
        border: none;
    }

    .form__field--borderless:focus {
        box-shadow: none;
    }

    .form__field[aria-invalid]:not(.is-filled) {
        background: var(--error-background);
        color: var(--error-color);
        border-color: var(--error-color);
    }

    .form__field[aria-invalid]:not(.is-filled)+.form__floating-label {
        color: var(--error-color);
    }

    .form__label {
        display: block;
        margin-bottom: 6px;
        color: var(--heading-color);
        font-weight: var(--text-font-bolder-weight);
    }

    .form__label--light {
        color: var(--text-color);
    }

    .form__submit {
        display: block;
        margin-top: 20px;
    }

    .form__submit--tight {
        margin-top: 12px;
        width: 100%;
    }


    @media screen and (min-width: 641px) {
        .form__submit--centered {
            margin-left: auto;
            margin-right: auto;
        }
    }

    /**
 * --------------------------------------------------------------------
 * INPUT WRAPPER
 * This is used to create list of fields, optionally with a label
 * --------------------------------------------------------------------
 */

    .form__input-wrapper {
        position: relative;
        width: 100%;
        margin-bottom: 12px;
    }

    .form__floating-label {
        position: absolute;
        left: 13px;
        top: 0;
        line-height: 48px;
        /* allows to center the field */
        font-size: 1rem;
        color: var(--text-color);
        transform: scale(1);
        transform-origin: left top;
        transition: transform 0.2s ease-in-out;
        pointer-events: none;
    }

    .form__field:focus+.form__floating-label,
    .form__field.is-filled+.form__floating-label,
    .select-wrapper.is-filled+.form__floating-label {
        transform: translateY(-6px) scale(0.8);
    }

    .form__input-wrapper--labelled .form__field {
        padding-top: 20px;
        padding-bottom: 3px;
    }

    .form__field--large+.form__floating-label {
        left: 18px;
        line-height: 60px;
    }

    .form__input-wrapper--labelled .form__field--large {
        padding-top: 20px;
        padding-bottom: 3px;
    }

    /**
 * --------------------------------------------------------------------
 * INPUT ROW
 * --------------------------------------------------------------------
 */

    .form__input-row {
        display: flex;
        flex-direction: column;
    }

    .form__input-row .form__submit {
        margin-top: 0;
    }

    @media screen and (min-width: 641px) {
        .form__input-row {
            flex-direction: row;
            align-items: flex-end;
            margin: 0 -6px;
        }

        .form__input-row:not(:last-child) {
            margin-bottom: 12px;
        }

        .form__input-row>.form__input-wrapper {
            margin-bottom: 0;
        }

        .form__input-row>* {
            margin-left: 6px;
            margin-right: 6px;
        }

        .form__input-row>.form__submit {
            margin-top: 0;
        }

        .form__input-row>.form__submit {
            flex: 1 0 auto;
            /* we let the submit button grow freely */
        }
    }

    /**
 * --------------------------------------------------------------------
 * CONNECTED INPUT
 * --------------------------------------------------------------------
 */

    .form__connected-item {
        display: flex;
        align-items: center;
        margin-bottom: 12px;
    }

    .form__connected-item .form__input-wrapper {
        margin-bottom: 0;
    }

    .form__connected-item .form__field {
        border-top-right-radius: 0;
        border-bottom-right-radius: 0;
        border-right: none;
        /* When connected with the icon, the box-shadow must be set inside */
    }

    .form__connected-item .form__field:focus {
        box-shadow: 0 0 0 1px var(--accent-color) inset;
    }

    .form__connected-item .form__connection {
        padding-left: 14px;
        padding-right: 14px;
        border-top-left-radius: 0;
        border-bottom-left-radius: 0;
    }

    .form__connected-item .form__connection svg {
        width: 23px;
        height: 23px;
    }

    /**
 * --------------------------------------------------------------------
 * FORM MAIN VARIATION (used when the form is the main element)
 * --------------------------------------------------------------------
 */

    .form--main {
        max-width: 350px;
        margin: 60px auto;
        text-align: center;
    }

    .form__header,
    .form__legend {
        margin-bottom: 30px;
    }

    .form__title {
        margin-bottom: 15px;
    }

    .form__secondary-action {
        margin-top: 32px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
    }

    .form__secondary-action>* {
        margin-bottom: 0;
    }

    @media screen and (min-width: 641px) {
        .form--main {
            margin-top: 110px;
            margin-bottom: 150px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * SELECT
 * --------------------------------------------------------------------
 */

    select::-ms-expand {
        display: none;
    }

    .select-wrapper {
        position: relative;
        color: currentColor;
        line-height: inherit;
        vertical-align: middle;
    }

    .select-wrapper svg {
        position: absolute;
        pointer-events: none;
        vertical-align: baseline;
        fill: currentColor;
    }

    .select-wrapper select {
        /* Disable built-in styles */
        -webkit-appearance: none;
        -moz-appearance: none;
        display: inline-block;
        color: inherit;
        cursor: pointer;
        border-radius: 0;
        /* Remove the ugly blue background on IE when a value is selected */
    }

    .select-wrapper select:focus::-ms-value {
        background: transparent;
        color: var(--text-color);
    }

    /* Make sure to have something easy to read... */
    .select-wrapper option {
        background: white;
        color: black;
    }

    .select-wrapper--transparent select {
        padding-right: 22px;
        background: transparent;
        border: none;
        font-size: inherit;
    }

    .select-wrapper--transparent svg {
        top: calc(50% - 4px);
        right: 4px;
        width: 12px;
        height: 8px;
    }

    .select-wrapper--primary {
        position: relative;
        background: var(--secondary-background);
    }

    .select-wrapper--primary select {
        width: 100%;
        padding: 0 36px 0 12px;
        height: 48px;
        border: 1px solid var(--form-border-color);
        border-radius: 2px;
        background: transparent;
        box-shadow: 0 -1px 1px rgba(var(--border-color-rgb), 0.3) inset;
        font-size: 1rem;
        font-size: max(1rem, 16px);
        /* for modern browser ; setting a min value of 16px is required for accessibility */
        transition: border-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
    }

    .select-wrapper--primary select:focus {
        border-color: var(--accent-color);
        box-shadow: 0 0 0 1px var(--accent-color);
        outline: none;
    }

    .select-wrapper--primary select:valid {
        color: var(--heading-color);
    }

    .select-wrapper--primary svg {
        width: 12px;
        height: 14px;
        top: calc(50% - 7px);
        right: 16px;
        opacity: 0.7;
    }

    .select-wrapper--primary.select-wrapper--small select {
        height: 44px;
        padding-left: 12px;
        padding-bottom: 1px;
        /* just for some pixel perfect alignment... but not sure if it's really good idea for cross-browser! */
    }

    .form__input-wrapper--labelled .select-wrapper--primary.is-filled select {
        padding-top: 16px;
    }

    /* Abstraction to just have a select button (without the actual select) */
    .select-button {
        position: relative;
        background: var(--secondary-background);
        color: currentColor;
        line-height: inherit;
        vertical-align: middle;
        width: 100%;
        padding: 0 36px 0 12px;
        height: 48px;
        border: 1px solid var(--form-border-color);
        border-radius: 2px;
        box-shadow: 0 -1px 1px rgba(var(--border-color-rgb), 0.3) inset;
        font-size: 1rem;
        text-align: left;
        transition: border-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
    }

    .select-button:focus {
        border-color: var(--accent-color);
        box-shadow: 0 0 0 1px var(--accent-color);
        outline: none;
    }

    .select-button svg {
        position: absolute;
        pointer-events: none;
        width: 12px;
        height: 14px;
        top: calc(50% - 7px);
        right: 16px;
        opacity: 0.7;
        vertical-align: baseline;
        fill: currentColor;
    }

    .select-button--mini {
        height: 32px;
        padding: 0 44px 0 10px;
        font-size: 0.85rem;
    }

    .select-button--mini svg {
        right: 11px;
    }

    /**
 * --------------------------------------------------------------------
 * CUSTOM CHECKBOX
 * --------------------------------------------------------------------
 */

    .checkbox-wrapper {
        position: relative;
        display: inline-block;
        vertical-align: middle;
        margin: 8px 0;
    }

    .checkbox-wrapper svg {
        position: absolute;
        width: 12px;
        height: 12px;
        left: 2px;
        top: calc(50% - 6px);
        transform: scale(0);
        transition: transform 0.2s ease-in-out;
        color: var(--secondary-background);
    }

    .checkbox-wrapper~label {
        vertical-align: middle;
        cursor: pointer;
    }

    .checkbox {
        display: block;
        margin-right: 10px;
        width: 16px;
        height: 16px;
        border: 1px solid var(--form-border-color);
        background: var(--secondary-background);
        box-shadow: 0 1px rgba(var(--border-color-rgb), 0.4);
        border-radius: 2px;
        -webkit-appearance: none;
        transition: border-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out, background 0.2s ease-in-out;
    }

    .checkbox:focus {
        border-color: var(--accent-color);
        box-shadow: 0 0 0 1px var(--accent-color);
        outline: none;
    }

    .checkbox:checked {
        background: var(--accent-color);
        border-color: var(--accent-color);
        box-shadow: none;
    }

    .checkbox:checked+svg {
        transform: scale(1);
    }

    .checkbox.is-selected~label {
        color: var(--accent-color);
        font-weight: var(--text-font-bolder-weight);
    }

    .checkbox,
    .checkbox~label {
        vertical-align: middle;
        cursor: pointer;
    }

    @media screen and (min-width: 1000px) {
        .checkbox-wrapper {
            margin: 12px 0;
        }
    }

    .gift-card__inner {
        padding: 30px 0;
    }

    .gift-card__main {
        position: relative;
        padding-top: 85px;
        text-align: center;
    }

    .gift-card__image {
        position: relative;
        width: 170px;
        height: 170px;
        top: -105px;
        border-radius: 100%;
        overflow: hidden;
        margin: 0 auto -75px auto;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
    }

    .gift-card__title {
        margin-bottom: 0;
    }

    .gift-card__amount {
        margin-bottom: 18px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 22px));
    }

    .gift-card__alert {
        margin-top: 20px;
    }

    .gift-card__code-container {
        max-width: 255px;
        margin: 0 auto 28px auto;
    }

    .gift-card__code {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 6px 15px;
        width: 100%;
        border: 1px solid var(--border-color);
        text-transform: uppercase;
        margin-bottom: 15px;
        border-radius: 3px;
        text-align: center;
    }

    .gift-card__expires-on {
        display: block;
        color: var(--product-in-stock-color);
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 15px));
    }

    .gift-card__expires-on::before {
        display: inline-block;
        content: "";
        width: 8px;
        height: 8px;
        margin-right: 0.7em;
        border-radius: 100%;
        background: currentColor;
        vertical-align: baseline;
    }

    .gift-card__share {
        padding-top: 15px;
        padding-bottom: 20px;
    }

    .gift-card__wallet {
        display: block;
