    /* This is a bit hacky, but it allows to have a clearfix when the search bar on mobile is expanded */
    #shopify-section-header::after {
        content: "";
        display: table;
        clear: both;
    }

    /**
 * --------------------------------------------------------------------
 * HEADER
 * --------------------------------------------------------------------
 */

    .header {
        position: relative;
        padding: 13px 0;
        background: var(--header-background);
        color: var(--header-text-color);
        transition: margin-bottom 0.25s ease-in-out;
    }

    .header__inner {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
    }

    .header__inner--centered {
        justify-content: center;
    }

    .header__logo-link {
        display: block;
    }

    .header__logo {
        display: inline-block;
        vertical-align: middle;
        margin-bottom: 0;
    }

    .header__logo-image {
        display: block;
        vertical-align: middle;
        max-height: 130px;
    }

    .header__mobile-nav {
        display: inline-block;
        margin-right: 20px;
    }

    .header__desktop-nav {
        position: relative;
        margin-right: 22px;
    }

    .header__mobile-nav-toggle {
        top: -1px;
        /* Slight alignment for pixel perfect :D */
    }

    .header__desktop-nav-toggle {
        height: 44px;
        padding: 0 15px;
        border: 1px solid var(--header-border-color);
        border-radius: 3px;
        font-weight: var(--text-font-bolder-weight);
        /* Safari 10 does not allow using flexbox on button... so we have to use an additional wrapper */
    }

    .header__desktop-nav-toggle>span {
        display: flex;
        align-items: center;
    }

    .header__desktop-nav-text {
        position: relative;
        top: 1px;
        /* Slight alignment for the pixel perfect */
    }

    .header__search-bar-wrapper {
        flex: 1 0 auto;
    }


    .header .icon--account,
    .header .icon--hamburger,
    .header .icon--hamburger-mobile,
    .header .icon--search,
    .header .icon--cart,
    .header .icon--close,
    .header .icon--cart1 {
        display: block;
    }

    .header .icon--account {
        width: 20px;
        height: 22px;
    }

    .header .icon--hamburger {
        width: 20px;
        height: 14px;
    }

    .header .icon--hamburger-mobile {
        width: 20px;
        height: 16px;
    }

    .header .icon--cart {
        width: 27px;
        height: 24px;
    }

    .header .icon--cart1 {
        width: 17px;
        height: 14px;
    }

    .header .icon--search {
        width: 22px;
        height: 22px;
        margin: 0 auto;
    }

    .header .icon--close {
        width: 19px;
        height: 19px;
    }

    @media screen and (max-width: 640px) {

        /* This trick allows to enforce a minimum height for header on mobile */
        .header {
            display: flex;
            align-items: center;
            min-height: 64px;
        }

        .header>.container {
            width: 100%;
        }

        /* On mobile, if the search is expanded by default, we must add extra margin to the header element to prevent the search to
     overlap the rest of the content */
        .header--search-expanded {
            margin-bottom: 59px;
        }
    }

    @media screen and (min-width: 641px) {
        .header {
            padding: 20px 0;
        }

        .header__inner {
            flex-wrap: nowrap;
        }

        .header__logo {
            margin-right: 35px;
        }
    }

    @media screen and (min-width: 1000px) {
        .icon--hamburger {
            margin-right: 15px;
        }
    }

    @media screen and (min-width: 1280px) {
        .header__logo {
            margin-right: 40px;
        }

        .header__desktop-nav {
            margin-right: 30px;
        }

        .header__desktop-nav-toggle {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
        }
    }

    /**
 * --------------------------------------------------------------------
 * HEADER ACTION LIST
 * --------------------------------------------------------------------
 */

    .header__action-list {
        display: flex;
        align-items: center;
        margin-left: auto;
    }

    .header__action-item {
        padding: 0 9px;
    }

    .header__action-item:last-child {
        padding-right: 4px;
        /* Last item is the cart, and we use a small padding to accommodate the presence of the cart item count */
    }

    .header__action-item-link {
        display: block;
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
    }

    .header__action-item-link--small {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        font-weight: normal;
    }

    .header__action-item-title {
        display: block;
        margin-bottom: -6px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        font-weight: normal;
    }

    .header__action-item--currency,
    .header__action-item--locale {
        margin-right: 25px;
        padding: 0 24px;
    }

    .header__currency-selector {
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
    }

    .header__action-item .icon--arrow-bottom {
        width: 12px;
        height: 8px;
        margin-left: 4px;
    }

    .header__action-item .icon--lock-2 {
        width: 12px;
        height: 15px;
    }

    .header__action-item .icon--lock-2+span {
        margin-left: 14px;
    }

    .header__cart-icon {
        margin-left: -2px;
    }

    .header__cart-count {
        display: inline-flex;
        position: absolute;
        top: -7px;
        align-items: center;
        justify-content: center;
        height: 20px;
        min-width: 20px;
        padding: 4px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
        font-weight: var(--text-font-bolder-weight);
        text-align: center;
        background: var(--header-accent-color);
        color: var(--secondary-background);
        border-radius: 1.75em;
        transition: transform 0.35s ease-in-out;
        will-change: transform;
        transform: scale(1.01);
        z-index: 1;
    }

    .header__cart-toggle[aria-expanded=true] .header__cart-count,
    .header__cart-toggle:hover .header__cart-count {
        transform: scale(1.2);
    }

    @media screen and (max-width: 640px) {

        /* This code is not optimal but the cart icon has a specific positioning so we override it this way */
        .header__cart-icon .icon-state__secondary.icon-state__secondary {
            left: 8px;
        }

        .header__action-item .icon--lock-2 {
            display: block;
        }

        /*
    IMPLEMENTATION NOTE:
    I am using a transition on margin-bottom instead of doing a simpler and more efficient transform. However the issue is that we are doing
    another transition on margin-bottom for the header. If I would apply a transform here, due to the fact the transform is hardware accelerated,
    they will move at a slightly different speed, which is not desirable. It's therefore either all HW-accelerated or not.
   */
        .header__search-bar-wrapper {
            visibility: hidden;
            position: absolute;
            /* We move it outside of the document for easier positioning for other elements */
            padding: 0 20px 0 20px;
            width: 100%;
            bottom: 0;
            left: 0;
            background: var(--header-background);
            z-index: -1;
            /* because the position is absolutely positioned it get a higher z-index, but we need to revert it to avoid any trouble */
            transition: visibility 0.25s ease-in-out, margin-bottom 0.25s ease-in-out;
        }

        .header__search-bar-wrapper.is-visible {
            visibility: visible;
            margin-bottom: -59px;
        }

        /* When the user focus it, it becomes a fixed element */
        .header__search-bar-wrapper.is-fixed {
            position: fixed;
            top: 0;
            left: 0;
            height: 100vh;
            z-index: 10;
        }
    }

    @media screen and (min-width: 641px) {
        .header__action-list {
            padding-left: 28px;
        }

        .header__action-item,
        .header__action-item-content {
            position: relative;
        }

        .header__action-item-content {
            max-width: -webkit-max-content;
            max-width: -moz-max-content;
            max-width: max-content;
        }

        .header__action-item .icon--lock-2 {
            vertical-align: text-top;
        }
    }

    @media screen and (min-width: 1000px) {
        .header__action-list {
            padding-left: 5px;
        }

        .header__action-item:not(:last-child)::after {
            position: absolute;
            content: "";
            right: 0;
            top: calc(50% - 17px);
            background: var(--header-border-color);
            height: 34px;
            width: 1px;
        }

        .header__action-item--currency {
            margin-right: 20px;
        }
    }

    @media screen and (min-width: 1000px) and (max-width: 1279px) {
        .header__action-item:not(.header__action-item--currency):not(.header__action-item--locale)::after {
            display: none;
        }

        .header__action-item--currency+.header__action-item--locale {
            padding-left: 9px;
        }

        /* Not really beautiful but coulnd't find a better way */
        .header__action-item.hidden-tablet-and-up:first-child+.header__action-item {
            padding-left: 35px;
        }
    }

    @media screen and (min-width: 1280px) {
        .header__action-item {
            padding: 0 35px;
        }

        .header__action-item:last-child {
            padding-right: 0;
        }

        .header__action-item--currency,
        .header__action-item--locale {
            margin-right: 0;
        }

        .header__cart-icon {
            display: inline-block;
            top: -1px;
            /* Slight adjustment for the pixel perfect muahah */
        }
    }

    /**
 * --------------------------------------------------------------------
 * SEARCH
 * --------------------------------------------------------------------
 */

    .search-bar {
        position: relative;
        min-width: 100%;
        padding-bottom: 15px;
        z-index: 1;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 15px));
    }

    /* Top part */
    .search-bar__top {
        position: relative;
        display: flex;
        height: 44px;
        align-items: center;
        border-radius: 10px;
        background: var(--secondary-background);
        color: var(--text-color);
        z-index: 1;
    }

    .search-bar__input-wrapper {
        position: relative;
        flex: 1 0 auto;
        height: 100%;
    }

    .search-bar__input {
        height: 100%;
        width: 100%;
        padding: 0 15px 1px 15px;
        border: none;
        /*background: transparent;*/
        line-height: normal;
        color: var(--heading-color);
        -webkit-appearance: none;
        border-radius: 10px 0 0 10px;
    }

    .search-bar__input::-moz-placeholder {
        color: var(--text-color);
        opacity: 1;
    }

    .search-bar__input:-ms-input-placeholder {
        color: var(--text-color);
        opacity: 1;
    }

    .search-bar__input::placeholder {
        color: var(--text-color);
        opacity: 1;
    }

    .search-bar__input::-ms-clear {
        display: none;
    }

    .search-bar__input:focus {
        outline: none;
    }

    .search-bar__input-clear {
        position: absolute;
        right: 15px;
        top: calc(50% - 9px);
        display: none;
        opacity: 0.5;
    }

    .search-bar__input-clear svg {
        display: block;
        width: 17px;
        height: 17px;
    }

    .search-bar__input.is-filled+.search-bar__input-clear {
        display: block;
    }

    .search-bar__filter {
        display: none;
        border-left: 1px solid var(--header-border-color);
    }

    .search-bar__filter-label {
        display: block;
        height: 44px;
        padding: 0 30px 0 25px;
        line-height: 43px;
        /* The -1px allows to account for rounding errors */
    }

    .search-bar__filter-label svg {
        margin-left: 11px;
        width: 12px;
        height: 8px;
    }

    .search-bar__submit {
        flex: none;
        width: 50px;
        height: 100%;
        color: var(--secondary-background);
        background: var(--header-accent-color);
        border-radius: 0 8px 8px 0;
    }

    .search-bar__submit svg {
        position: relative;
    }

    .search-bar__submit .icon--search {
        width: 21px;
        height: 21px;
    }

    .search-bar__submit .icon--search-loader {
        display: none;
        width: 24px;
        height: 24px;
        margin: 0 auto;
    }

    /* Inner */
    .search-bar__inner {
        position: absolute;
        visibility: hidden;
        left: -20px;
        top: calc(100% + 8px);
        width: 100vw;
        height: 100vh;
        overflow: hidden;
        color: var(--text-color);
        background: var(--secondary-background);
    }

    @supports (--css: variables) {
        .search-bar__inner {
            height: calc(100vh - var(--header-height) - 25px);
        }
    }

    .search-bar__inner-animation {
        height: 100%;
    }

    .search-bar__results,
    .search-bar__menu-wrapper {
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        background: var(--secondary-background);
        box-shadow: 0 1px 5px 2px rgba(0, 0, 0, 0.1);
        visibility: hidden;
        transition: visibility 0.1s ease-in-out;
    }

    .search-bar__results[aria-hidden=false],
    .search-bar__menu-wrapper[aria-hidden=false] {
        visibility: visible;
    }

    .search-bar.is-expanded .search-bar__inner-animation {
        visibility: visible;
    }

    .search-bar__empty-state {
        text-align: center;
        padding: 50px 0;
    }

    /* To reduce the complexity of JavaScript and use Liquid as much as possible, the live search will output both
   the result for products and/or pages and blogs. We therefore then hide possible duplicate status in CSS */
    .search-bar__result-products~.search-bar__empty-state {
        display: none;
    }

    /* Quick links */
    .search-bar__menu-title {
        margin-bottom: 4px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
    }

    .search-bar__menu-wrapper {
        padding: 18px 0 12px 0;
        height: 100%;
        overflow: auto;
        -ms-scroll-chaining: none;
        overscroll-behavior: none;
    }

    .search-bar__menu-title,
    .search-bar__menu-link {
        padding-left: 20px;
        padding-right: 20px;
    }

    .search-bar__menu-link {
        display: block;
        padding-top: 6px;
        padding-bottom: 6px;
        transition: color 0.15s ease-in-out, background 0.15s ease-in-out;
    }

    .search-bar__menu-link:hover,
    .search-bar__menu-link:focus {
        background: var(--accent-background);
        color: var(--accent-color);
        outline: none;
    }

    /* Results */
    .search-bar__results .skeleton-container {
        display: none;
    }

    .search-bar__results {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        height: 100%;
        overflow: auto;
        -ms-scroll-chaining: none;
        overscroll-behavior: none;
    }

    .search-bar__result-category {
        margin: 0;
        padding: 4px 20px;
        text-transform: uppercase;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
        font-weight: var(--text-font-bolder-weight);
        background: var(--background);
        box-shadow: 0 1px var(--border-color), 0 -1px var(--border-color);
    }

    .search-bar__result-item {
        display: flex;
        align-items: center;
        padding: 15px 20px;
        transition: background 0.2s ease-in-out;
    }

    .search-bar__result-item:not(.search-bar__result-item--skeleton):hover,
    .search-bar__result-item:not(.search-bar__result-item--skeleton):focus {
        background: var(--accent-background);
        outline: none;
    }

    .search-bar__result-item--skeleton {
        max-width: 300px;
    }

    .search-bar__image-container {
        flex: none;
        width: 60px;
        margin-right: 20px;
    }

    .search-bar__image-container img {
        color: transparent;
        /* allows to remove the alt on Firefox during image loading */
    }

    .search-bar__item-info {
        flex: 1 0 0;
    }

    .search-bar__item-title {
        margin-bottom: 0;
        line-height: 1.4;
    }

    .search-bar__item-price {
        color: var(--accent-color);
    }

    .search-bar__result-link {
        display: block;
        padding: 5px 20px;
        transition: color 0.2s ease-in-out, background 0.2s ease-in-out;
    }

    .search-bar__result-link:hover,
    .search-bar__result-link:focus {
        color: var(--accent-color);
        background: var(--accent-background);
        outline: none;
    }

    .search-bar__view-all {
        display: block;
        padding: 10px;
