        color: var(--secondary-button-text-color) !important;
        font-weight: var(--text-font-bolder-weight) !important;
        font-size: var(--base-text-font-size) !important;
        cursor: pointer;
        transition: background 0.25s ease-in-out, color 0.25s ease-in-out, box-shadow 0.25s ease-in-out;
    }

    .shopify-payment-button__button--unbranded:hover {
        background: rgba(var(--secondary-button-background-rgb), 0.8) !important;
    }

    .shopify-payment-button__button--branded {
        border-radius: 3px;
        overflow: hidden;
        min-height: 48px;
    }

    .shopify-payment-button__more-options {
        margin-top: 8px;
        color: var(--link-color);
        transition: color 0.2s ease-in-out;
    }

    .shopify-payment-button__more-options:not([disabled]):hover {
        text-decoration: none;
        color: var(--link-color-hover);
    }

    .shopify-payment-button__more-options[aria-hidden=true] {
        display: none;
    }

    /**
 * --------------------------------------------------------------------
 * BLOCK LIST
 * --------------------------------------------------------------------
 */

    .product-block-list__item--trust .icon--lock {
        width: 18px;
        height: 24px;
        color: var(--heading-color);
    }

    /* This code is not super clean, but it's due to the wish of the designer to have some pixel perfect alignment that
   are specific JUST for this element and break the generic abstractions... thanks dude :D */
    .product-block-list__item--shipping .shipping-estimator {
        margin-bottom: 10px;
        margin-top: -0.435em;
    }

    .product-block-list__item--shipping .shipping-estimator__results {
        margin-top: 26px;
        margin-bottom: -10px;
    }

    .product__refund-policy-link {
        display: flex;
        align-items: center;
        justify-content: space-between;
        width: 100%;
    }

    .product__refund-policy-link svg {
        width: 8px;
        height: 12px;
    }

    @media screen and (max-width: 640px) {
        .product-block-list__item:first-child .card {
            border-top: none;
        }
    }

    @media screen and (max-width: 999px) {

        /* we have a logic on desktop with overflow scroller and we must force it to disabled on mobile */
        .product-block-list__wrapper {
            min-height: 0 !important;
        }

        .product-block-list__item--info>.card {
            top: 0 !important;
        }
    }

    @media screen and (min-width: 1000px) {
        .product-block-list {
            position: relative;
        }

        .product-block-list__wrapper {
            width: calc(50% - 15px);
            margin-left: 0;
        }

        .product-block-list__item--info {
            position: absolute;
            top: 0;
            right: 0;
            width: calc(50% - 15px);
            height: 100%;
        }
    }

    @media screen and (min-width: 1280px) {
        .product-block-list--medium .product-block-list__wrapper {
            width: calc(55% - 15px);
        }

        .product-block-list--medium .product-block-list__item--info {
            width: calc(45% - 15px);
        }

        .product-block-list--large .product-block-list__wrapper {
            width: calc(60% - 15px);
        }

        .product-block-list--large .product-block-list__item--info {
            width: calc(40% - 15px);
        }
    }

    /**
 * --------------------------------------------------------------------
 * FEATURED PRODUCT (HOMEPAGE)
 * --------------------------------------------------------------------
 */

    /* When within the modal we need to remove the border */
    .modal .featured-product .card {
        border: none;
    }

    .modal .featured-product .card:first-child {
        border-right: 1px solid var(--border-color);
    }

    @media screen and (min-width: 1000px) {
        .featured-product {
            display: table;
            width: 100%;
            table-layout: fixed;
        }

        .featured-product>* {
            display: table-cell;
            vertical-align: top;
            width: 50%;
        }

        .featured-product> :first-child {
            border-radius: 3px 0 0 3px;
        }

        .featured-product> :last-child {
            border-radius: 0 3px 3px 0;
            border-left: none;
        }
    }

    /**
 * --------------------------------------------------------------------
 * PRODUCT LABEL
 * --------------------------------------------------------------------
 */

    .product-label {
        display: inline-block;
        padding: 4px 10px;
        color: #ffffff;
        border-radius: 3px;
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        line-height: 1;
        vertical-align: top;
        width: -webkit-max-content;
        width: -moz-max-content;
        width: max-content;
    }

    .product-label--on-sale {
        background: var(--badge_discount_background);
        color: var(--badge_discount_color);
    }

    .product-label--custom1 {
        background: var(--product-custom-label-1-background);
        color: var(--product-custom-label-1-color);
    }

    .product-label--custom2 {
        background: var(--product-custom-label-2-background);
        color: var(--product-custom-label-2-color);
    }

    /**
 * --------------------------------------------------------------------
 * PRODUCT PRICE
 * ---------
 -----------------------------------------------------------
 */

    .price-list {
        display: inline-flex;
        align-items: baseline;
        line-height: 1;
    }

    .price {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 24px));
        color: var(--accent-color);
    }

    .price--highlight {
        margin-right: 0.7em;
        color: var(--product-on-sale-accent);
    }

    .price--compare {
        position: relative;
        color: var(--text-color);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
        text-decoration: line-through;
        -webkit-text-decoration-color: rgba(var(--text-color-rgb), 0.7);
        text-decoration-color: rgba(var(--text-color-rgb), 0.7);
    }

    /**
 * --------------------------------------------------------------------
 * INVENTORY AND BAR
 * --------------------------------------------------------------------
 */

    .inventory {
        position: relative;
        display: block;
        padding-left: 1.4em;
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        line-height: 1.2;
    }

    .inventory::before {
        position: absolute;
        display: inline-block;
        content: "";
        width: 8px;
        height: 8px;
        left: 0;
        top: 0.45em;
        border-radius: 100%;
        background: currentColor;
    }

    .inventory--high {
        color: var(--product-in-stock-color);
    }

    .inventory--low {
        color: var(--product-low-stock-color);
    }

    .inventory-bar {
        position: relative;
        display: block;
        margin: 16px 0 10px 0;
        width: 100%;
        height: 4px;
        border-radius: 3px;
        background: var(--border-color);
        overflow: hidden;
    }

    .inventory-bar--hidden {
        display: none;
    }

    .inventory-bar__progress {
        position: absolute;
        left: 0;
        top: 0;
        height: 100%;
        width: 0;
        display: block;
        transition: width 1.15s ease-in-out;
    }

    .inventory--high+.inventory-bar>.inventory-bar__progress {
        background: var(--product-in-stock-color);
    }

    .inventory--low+.inventory-bar>.inventory-bar__progress {
        background: var(--product-low-stock-color);
    }

    @media screen and (min-width: 641px) {
        .inventory {
            font-size: 1rem;
        }

        .inventory-bar {
            margin-top: 23px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * COLOR SWATCH
 * --------------------------------------------------------------------
 */

    .color-swatch-list {
        margin: -2px -6px 0 -6px;
        /* We have to take into account the box-shadow and inner spacing added when an element is active */
        padding-left: 4px;
    }

    .color-swatch {
        position: relative;
        display: inline-block;
        margin: 6px;
        vertical-align: middle;
    }

    .color-swatch__radio {
        position: absolute;
        height: 0;
        width: 0;
        opacity: 0;
    }

    .color-swatch__item {
        position: relative;
        display: block;
        width: 18px;
        height: 18px;
        cursor: pointer;
        background-size: cover;
    }

    .color-swatch__item svg {
        display: none;
    }

    .color-swatch__item-link {
        display: none;
        position: relative;
        padding-left: 8px;
        padding-right: 8px;
        height: 18px;
        background-color: var(--secondary-background);
        box-shadow: 0 0 0 1px var(--form-border-color) inset;
        border-radius: 10px;
        width: auto;
        line-height: 18px;
        font-size: 12px;
    }

    .color-swatch__button {
        vertical-align: middle;
    }

    .color-swatch__button--labelled {
        display: flex;
        align-items: center;
        justify-content: flex-start;
    }

    .color-swatch__label {
        display: inline-block;
        vertical-align: middle;
        margin-left: 14px;
    }

    .color-swatch__radio:checked+.color-swatch__item::after,
    .color-swatch__button.is-selected .color-swatch__item::after {
        position: absolute;
        content: "";
        width: calc(100% + 8px);
        height: calc(100% + 8px);
        top: -4px;
        left: -4px;
        border-radius: 3px;
        border: 2px solid var(--accent-color);
    }

    .color-swatch__button.is-selected .color-swatch__label {
        font-weight: var(--text-font-bolder-weight);
        color: var(--accent-color);
    }

    .color-swatch--white .color-swatch__item {
        box-shadow: 0 0 0 1px var(--form-border-color) inset;
    }

    /* The view more is used on listing, to restrict the number of displayed swatches */
    .color-swatch--view-more~.color-swatch {
        display: none;
    }

    .color-swatch--view-more .color-swatch__item {
        display: none;
    }

    .color-swatch--view-more .color-swatch__item-link {
        display: block;
    }

    /** Large list variation **/
    .color-swatch-list--large {
        margin: -4px -8px 0 -8px;
        /* We have to take into account the box-shadow and inner spacing added when an element is active */
    }

    .color-swatch-list--large .color-swatch {
        margin: 8px;
    }

    .color-swatch-list--large .color-swatch__item {
        width: 36px;
        height: 36px;
    }

    /** Stack list variation **/
    .color-swatch-list--stack {
        margin: -3px -7px 0 -7px;
        /* We have to take into account the box-shadow and inner spacing added when an element is active */
    }

    .color-swatch-list--stack .color-swatch__item {
        width: 16px;
        height: 16px;
    }

    .color-swatch-list--stack .color-swatch {
        display: block;
        margin: 7px;
    }

    /* Disabled variation */
    .color-swatch--disabled .color-swatch__item::before {
        position: absolute;
        content: "";
        left: 0;
        top: 0;
        height: 100%;
        width: 100%;
        background: rgba(var(--secondary-background-rgb), 0.5);
    }

    .color-swatch--disabled svg {
        display: block;
        position: absolute;
        z-index: 1;
        width: 14px;
        height: 14px;
        top: calc(50% - 7px);
        left: calc(50% - 7px);
        color: #4a4a4a;
    }

    /**
 * --------------------------------------------------------------------
 * BLOCK SWATCH
 * --------------------------------------------------------------------
 */

    .block-swatch-list {
        margin: -3px -4px 0 -4px;
        /* We need to take into account the box-shadow height when element is active */
        padding-left: 2px;
    }

    .block-swatch {
        display: inline-block;
        margin: 4px;
    }

    .block-swatch__radio {
        position: absolute;
        height: 0;
        width: 0;
        opacity: 0;
    }

    .block-swatch__item {
        display: block;
        padding: 6px 16px 7px 16px;
        text-align: center;
        border: 1px solid var(--form-border-color);
        border-radius: 3px;
        vertical-align: middle;
        cursor: pointer;
        box-shadow: 0 1px 1px rgba(var(--border-color-rgb), 0.25);
    }

    .block-swatch__radio:checked+.block-swatch__item {
        box-shadow: 0 0 0 1px var(--accent-color);
        border-color: var(--accent-color);
        background: rgba(var(--accent-color-rgb), 0.06);
        color: var(--accent-color);
    }

    .block-swatch--disabled .block-swatch__item-text {
        position: relative;
        opacity: 0.5;
    }

    .block-swatch--disabled .block-swatch__item-text::after {
        position: absolute;
        content: "";
        width: calc(100% + 6px);
        height: 1px;
        top: calc(50% + 1px);
        left: -3px;
        background: currentColor;
    }

    /**
 * --------------------------------------------------------------------
 * VARIANT SWATCH
 * --------------------------------------------------------------------
 */

    .variant-swatch-list {
        margin: -5px -5px -2px -4px;
    }

    .variant-swatch {
        display: inline-block;
        margin: 5px;
        vertical-align: middle;
    }

    .variant-swatch__radio {
        position: absolute;
        height: 0;
        width: 0;
        opacity: 0;
    }

    .variant-swatch__item {
        position: relative;
        display: block;
        width: 64px;
        padding: 2px;
        cursor: pointer;
        overflow: hidden;
        border: 2px solid transparent;
    }

    .variant-swatch__item svg {
        display: none;
    }

    .variant-swatch__radio:checked+.variant-swatch__item {
        border-color: var(--accent-color);
        border-radius: 3px;
    }

    /* Disabled variation */
    .variant-swatch--disabled img {
        opacity: 0.5;
    }

    .variant-swatch--disabled svg {
        display: block;
        position: absolute;
        z-index: 1;
        width: 14px;
        height: 14px;
        top: calc(50% - 7px);
        left: calc(50% - 7px);
        color: #4a4a4a;
    }

    /**
 * --------------------------------------------------------------------
 * PRODUCT ITEM
 * --------------------------------------------------------------------
 */

    .product-item {
        position: relative;
        padding: 22px;
        min-width: 0;
        flex-shrink: 0;
        background: var(--secondary-background);
        white-space: normal;
        transform: scale(.98);
        box-shadow: 0px 10px 15px -20px;
        border-radius: 18px;
        border: none;
    }

    .product-item::after {
        content: "";
        position: absolute;
        width: 100%;
        height: 100%;
        left: 0;
        top: 0;
        z-index: 2;
        /* needed to overlap the labels (if any) */
        pointer-events: none;
    }

    .product-item__image-wrapper {
        display: block;
        margin-bottom: 20px;
    }

    .product-item__image-wrapper .placeholder-svg {
        height: auto;
    }

    .product-item__secondary-image {
        display: none;
    }

    .product-item__label-list {
        position: absolute;
        top: 11px;
        left: -1px;
        z-index: 2;
        font-size: 0;
    }

    .product-item__label-list>.product-label {
        display: block;
        margin-bottom: 5px;
        border-radius: 15px;
        padding: 4px 12px 4px 12px;
        margin-left: 12px;
    }

    .product-item__info {
        min-width: 0;
    }

    .product-item__price-list:first-child {
        margin-bottom: 10px;
    }

    /* This trick is done to add some spacing in case the prices fall into two lines */
    .product-item__price-list {
        margin-top: -5px;
        margin-bottom: -5px;
    }

    .product-item__price-list .price {
        display: inline-block;
    }

    .product-item__vendor {
        display: block;
        margin-bottom: 6px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
        text-transform: uppercase;
    }

    .product-item__vendor,
    .product-item__title {
        display: block;
        line-height: 1.55;
    }

    .product-item__title {
        margin-bottom: 12px;
    }

    .product-item__title+.product-item__vendor {
        margin-bottom: 12px;
        margin-top: -4px;
    }

    .product-item__swatch-list {
        margin: -2px 0 12px 0;
        /* On the collection page, we do not show more than one line */
        white-space: nowrap;
        overflow: hidden;
    }

    .product-item__price-info {
        margin-top: 10px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        line-height: 1;
    }

    .product-item .price {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 18px));
    }

    .product-item .price--compare {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    .product-item__reviews-badge {
        display: block;
        margin: 17px 0;
    }

    .product-item__inventory {
        margin-top: 14px;
    }

    .product-item__inventory::before {
        top: 0.3em;
    }

    .product-item__inventory {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
    }

    @media (-moz-touch-enabled: 0),
    (hover: hover) {

        .product-item__image-wrapper--with-secondary .product-item__primary-image,
        .product-item__image-wrapper--with-secondary .product-item__secondary-image {
            transition: opacity 0.2s ease-in-out, visibility 0.2s ease-in-out;
        }

        .product-item__image-wrapper--with-secondary .product-item__secondary-image {
            display: block;
            -o-object-fit: contain;
            object-fit: contain;
            -o-object-position: center;
            object-position: center;
            visibility: hidden;
            opacity: 0;
        }

        .product-item__image-wrapper--with-secondary:hover .product-item__primary-image {
            opacity: 0;
            visibility: hidden;
        }

        .product-item__image-wrapper--with-secondary:hover .product-item__secondary-image {
            visibility: visible;
        }

        .product-item__image-wrapper--with-secondary:hover .product-item__secondary-image.lazyloaded {
            opacity: 1;
        }
    }

    @media screen and (min-width: 641px) {
        .product-item__title {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
        }

        .product-item--vertical .price:not(.price--compare),
        .product-item--list .price:not(.price--compare) {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 20px));
        }
    }

    @media screen and (min-width: 1000px) {
        .product-item__label-list {
            left: 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * PRODUCT ITEM (VERTICAL AND HORIZONTAL VARIATION)
 * --------------------------------------------------------------------
 */

    .product-item--vertical .product-item__action-list,
    .product-item--horizontal .product-item__action-list {
        margin: 20px 0 5px 0;
    }

    .product-item--vertical .product-item__action-button,
    .product-item--horizontal .product-item__action-button {
        padding-left: 10px;
        padding-right: 10px;
    }

    .product-item--vertical .product-item__action-list--list-view-only,
    .product-item--vertical .product-item__action-button--list-view-only,
    .product-item--horizontal .product-item__action-list--list-view-only,
    .product-item--horizontal .product-item__action-button--list-view-only {
        display: none;
    }

    .product-item--vertical .product-item__action-button--list-view-only+.product-item__action-button,
    .product-item--horizontal .product-item__action-button--list-view-only+.product-item__action-button {
        margin-top: 0;
    }

    @media screen and (min-width: 1000px) {
        .product-item--vertical .product-item__action-list {
            margin: 15px -5px -5px -5px;
        }

        .product-item--vertical .product-item__action-button {
            flex: 1 0 auto;
            margin: 5px !important;
        }
    }

    /**
 * --------------------------------------------------------------------
 * PRODUCT ITEM (HORIZONTAL AND LIST VARIATION)
 * --------------------------------------------------------------------
 */

    .product-item--horizontal,
    .product-item--list {
        display: flex;
    }

    .product-item--horizontal .product-item__info,
    .product-item--list .product-item__info {
        padding: 4px 0;
        flex: 1 0 0;
    }

    .product-item--horizontal .product-item__image-wrapper,
    .product-item--list .product-item__image-wrapper {
        flex: none;
        width: 120px;
        margin: 0 20px 0 0;
    }

    .product-item--horizontal .product-item__action-list,
    .product-item--list .product-item__action-list {
        align-self: center;
    }

    .product-item--horizontal .spr-starrating.spr-starrating {
        height: 11px;
    }

    .product-item--horizontal .spr-starrating .spr-icon.spr-icon {
        width: 11px;
        height: 11px;
    }

    @media screen and (max-width: 640px) {

        .product-item--horizontal,
        .product-item--list {
            width: 100% !important;
        }

        .product-list--collection .product-item__label-list,
        .product-list--stackable .product-item__label-list {
            left: 0;
        }

        .product-list--collection .spr-starrating.spr-starrating,
        .product-list--stackable .spr-starrating.spr-starrating {
            height: 11px;
        }

        .product-list--collection .spr-starrating .spr-icon.spr-icon,
        .product-list--stackable .spr-starrating .spr-icon.spr-icon {
            width: 11px;
            height: 11px;
        }
    }

    @media screen and (min-width: 641px) {
        .product-item--horizontal .product-item__image-wrapper {
            width: 110px;
            margin-right: 20px;
        }

        .product-item--horizontal .product-item__info {
            flex: 1 0 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * PRODUCT ITEM (LIST VARIATION)
 * --------------------------------------------------------------------
 */

    @media screen and (max-width: 640px) {
        .product-item__action-list {
            margin-top: 20px;
        }
    }

    @media screen and (min-width: 641px) {
        .product-item--list {
            width: 100% !important;
            align-items: center;
            padding-right: 25px;
        }

        .product-item--list .product-item__title {
            font-size: 1rem;
        }

        .product-item--list .product-item__image-wrapper {
            width: 180px;
            margin-right: 30px;
        }

        .product-item--list .product-item__info {
            display: flex;
            justify-content: space-between;
            flex: 1 0 0;
            margin: 15px 0 15px 0;
        }

        .product-item--list .product-item__action-list {
            display: flex;
            margin-left: 30px;
            min-width: 180px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * PRODUCT ITEM (COMPACT VARIATION)
 * --------------------------------------------------------------------
 */

    .product-item--compact .product-item__info {
        padding-top: 0;
    }

    .product-item--compact .product-item__price-list:first-child {
        margin-bottom: 8px;
    }

    .product-item--compact .product-item__reviews-badge {
        margin: 15px 0;
    }

    .promo-block {
        position: relative;
        display: flex;
        min-height: 240px;
        padding: 20px 24px;
        border-radius: 3px;
        overflow: hidden;
    }

    .promo-block--small {
        min-height: 220px;
    }

    .promo-block--large {
        min-height: 260px;
    }

    .promo-block--top-left,
    .promo-block--top-center,
    .promo-block--top-right {
        align-items: flex-start;
    }

