    .rte {
        word-break: break-word;
        /* Prevent long words to go outside the container */
    }

    /* Simple, minimum clearfix added to every RTE text to avoid issue with float */
    .rte::after {
        content: "";
        display: block;
        clear: both;
    }

    .rte h1,
    .rte h2,
    .rte h3,
    .rte h4,
    .rte h5,
    .rte h6 {
        margin: 1em 0;
        font-family: var(--heading-font-family);
