        width: 2px;
        height: 10px;
    }

    [aria-expanded=true] .plus-button::before,
    [aria-expanded=true] .plus-button::after {
        transform: translate(-50%, -50%) rotate(90deg);
    }

    [aria-expanded=true] .plus-button::before {
        opacity: 0;
    }

    @media screen and (min-width: 641px) {
        .plus-button--large {
            width: 14px;
            height: 14px;
        }

        .plus-button--large::before {
            width: 14px;
        }

        .plus-button--large::after {
            height: 14px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * SHOPIFY CHALLENGE
 * --------------------------------------------------------------------
 */

    .shopify-challenge__container {
        margin-top: 50px;
        margin-bottom: 50px;
        text-align: center;
    }

    .shopify-challenge__button.shopify-challenge__button {
        position: relative;
        display: inline-block;
        padding: 9px 30px;
        min-height: 48px;
        line-height: normal;
        border-color: var(--primary-button-background);
        border-radius: 2px;
        text-align: center;
        font-weight: var(--text-font-bolder-weight);
        font-size: var(--base-text-font-size);
        cursor: pointer;
        transition: background 0.25s ease-in-out, color 0.25s ease-in-out, border 0.25s ease-in-out;
        background: var(--primary-button-background);
        color: var(--primary-button-text-color);
    }

    .shopify-challenge__button.shopify-challenge__button:hover {
        background: rgba(var(--primary-button-background-rgb), 0.8);
    }

    @media screen and (min-width: 641px) {
        .shopify-challenge__container {
            margin-top: 100px;
            margin-bottom: 100px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * SHOPIFY POLICY CONTAINER
 * --------------------------------------------------------------------
 */

    .shopify-policy__container {
        max-width: 800px;
    }

    .shopify-policy__title {
        margin: 30px 0;
    }

    .shopify-policy__title h1 {
        margin-bottom: 0;
        font-family: var(--heading-font-family);
        font-weight: var(--heading-font-weight);
        font-style: var(--heading-font-style);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 24px));
        line-height: 1.45;
        color: var(--heading-color);
    }

    @media screen and (min-width: 641px) {
        .shopify-policy__title {
            margin: 30px 0;
        }

        .shopify-policy__title h1 {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 28px));
            line-height: 1.45;
        }
    }

    /**
 * --------------------------------------------------------------------
 * ANNOUNCEMENT BAR
 * --------------------------------------------------------------------
 */

    .announcement-bar {
        position: relative;
        display: block;
        font-weight: var(--text-font-bolder-weight);
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
        border-bottom: 1px solid var(--header-border-color);
    }

    .announcement-bar__content {
        display: block;
        padding: 4px 0;
        margin-bottom: 0;
    }

    .announcement-bar__content--center {
        text-align: center;
    }

    @media screen and (max-width: 640px) {
        .announcement-bar__inner {
            text-align: center;
            /* Always centered on mobile no matter the setting */
        }
    }

    @media screen and (min-width: 641px) {
        .announcement-bar {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
            text-align: left;
        }

        .announcement-bar__inner {
            display: flex;
            align-items: center;
        }

        .announcement-bar__content {
            padding: 7px 0;
            margin-right: auto;
        }

        .announcement-bar__content--center {
            margin-left: auto;
            padding-left: 0px;
            padding-left: var(--announcement-bar-button-width, 0px);
            /* We have to shift by the button width to center visually */
        }

        .announcement-bar__button {
            padding: 7px 18px 7px 15px;
            background: var(--header-accent-color);
            color: var(--secondary-background);
            box-shadow: 0 1px var(--header-accent-color);
        }

        .announcement-bar__button svg {
            display: inline-block;
            width: 20px;
            height: 17px;
            margin-right: 12px;
            vertical-align: text-bottom;
        }

        .announcement-bar__close-container {
            position: relative;
        }

        .announcement-bar__close {
            position: absolute;
            top: 25px;
            right: 0;
            color: var(--heading-color);
            transition: color 0.2s ease-in-out;
        }

        .announcement-bar__close:hover {
            color: var(--accent-color);
        }

        .announcement-bar__close svg {
            width: 19px;
            height: 19px;
        }

        .announcement-bar__newsletter {
            height: 0;
            overflow: hidden;
            visibility: hidden;
            text-align: center;
            transition: height 0.5s cubic-bezier(0.77, 0, 0.175, 1), visibility 0.5s cubic-bezier(0.77, 0, 0.175, 1);
        }

        .announcement-bar__newsletter[aria-hidden=false] {
            visibility: visible;
        }

        .announcement-bar__newsletter-inner {
            margin: 50px 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * OFFER ITEM
 * --------------------------------------------------------------------
 */

    .offer-item {
        padding: 20px;
        background: var(--secondary-background);
        border: 1px solid var(--border-color);
        border-radius: 3px;
    }

    .offer-item__image-wrapper {
        min-width: 70px;
        max-width: 70px;
        margin-bottom: 14px;
    }

    .offer-item__title {
        margin-bottom: 6px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 17px));
    }

    .offer-item__content {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 14px));
    }

    @media screen and (min-width: 641px) {
        .offer-item {
            padding: 28px 30px;
        }

        .offer-item__image-wrapper {
            min-width: 110px;
            max-width: 110px;
        }
    }

    @media screen and (min-width: 1280px) {
        .offer-item--inline {
            display: flex;
            align-items: center;
        }

        .offer-item--inline .offer-item__image-wrapper {
            margin: 0 30px 0 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * IMAGE WITH TEXT
 * --------------------------------------------------------------------
 */

    .image-with-text {
        display: flex;
        flex-direction: column;
    }

    .image-with-text__image-container {
        margin-bottom: 25px;
    }

    @media screen and (max-width: 999px) {
        .image-with-text__image-container {
            width: 100% !important;
            order: -1;
            /* Make sure the image is always coming first on small screens */
        }
    }

    @media screen and (min-width: 1000px) {
        .image-with-text {
            flex-direction: row;
            align-items: center;
            justify-content: center;
        }

        .image-with-text__image-container {
            max-width: 50%;
            /* Make sure that we constraint a maximum and minimum width no matter what the merchant choose to keep the text readable */
            min-width: 30%;
        }

        .image-with-text__image-container,
        .image-with-text__text-container {
            width: 50%;
            margin: 0;
        }

        .image-with-text__text-container:last-child {
            padding-left: 60px;
        }

        .image-with-text__text-container:first-child {
            text-align: right;
            padding-right: 60px;
        }

        .image-with-text__text-container:first-child .image-with-text__text-aligner {
            display: inline-block;
            text-align: left;
        }
    }

    @media screen and (min-width: 1000px) {
        .image-with-text__image-container {
            max-width: none;
            min-width: 0;
        }
    }

    @media screen and (min-width: 1280px) {
        .image-with-text__text-container:last-child {
            padding-left: 75px;
        }

        .image-with-text__text-container:first-child {
            padding-right: 75px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * NEWSLETTER
 * --------------------------------------------------------------------
 */

    .newsletter {
        /*margin-top: 30px;*/
    }

    .newsletter__form {
        padding-bottom: 10px;
    }

    .newsletter__text {
        margin-top: 16px;
    }

    /* Compact variation */
    .newsletter--compact .newsletter__form {
        padding-bottom: 0;
    }

    .newsletter--compact .newsletter__text {
        margin-top: 16px;
    }

    /**
 * --------------------------------------------------------------------
 * QUICK LINKS
 * --------------------------------------------------------------------
 */

    .quick-links {
        display: flex;
        flex-wrap: wrap;
        text-align: center;
        border-radius: 3px;
        list-style: none;
        background: var(--secondary-background);
        border: 1px solid var(--border-color);
        font-size: calc(var(--default-text-font-size) + 1px);
    }

    .quick-links__link {
        display: flex;
        justify-content: center;
        align-items: center;
        flex: 0 0 auto;
        width: 50%;
        /* we cannot use flex-basis due to a bug in IE11 as flex-basis does not take into account padding in this browser */
        box-shadow: 1px 0 var(--border-color), 0 1px var(--border-color);
        padding: 20px 10px;
        word-break: break-all;
        word-break: break-word;
        -webkit-hyphens: auto;
        -ms-hyphens: auto;
        hyphens: auto;
        text-transform: none;
        transition: color 0.2s ease-in-out;
    }

    .quick-links__link:hover {
        color: var(--accent-color);
    }

    .quick-links__link--grow {
        flex-grow: 1;
    }

    .quick-links__image-container {
        display: block;
        margin: 0 auto;
        flex: 1 1 auto;
        font-size: 0;
    }

    .quick-links__image-ie-fix {
        margin: 0 auto;
        transition: transform 0.3s ease-in-out;
    }

    @media (-moz-touch-enabled: 0),
    (hover: hover) {
        .features--animate-zoom .quick-links__link:hover .quick-links__image-ie-fix {
            transform: scale(1.05);
        }
    }

    @media screen and (min-width: 641px) {
        .quick-links__link {
            padding: 24px;
            width: 33.333333%;
            /* we cannot use flex-basis due to a bug in IE11 as flex-basis does not take into account padding in this browser */
        }
    }

    @media screen and (min-width: 1000px) {
        .quick-links__link {
            width: 16.66666667%;
            /* we cannot use flex-basis due to a bug in IE11 as flex-basis does not take into account padding in this browser */
        }
    }

    /**
 * --------------------------------------------------------------------
 * BREADCRUMB
 * --------------------------------------------------------------------
 */

    .breadcrumb__list {
        display: flex;
        align-items: center;
        list-style: none;
    }

    .breadcrumb__list svg {
        margin: 0 7px;
        width: 6px;
        height: 8px;
        vertical-align: inherit;
    }

    /**
 * --------------------------------------------------------------------
 * LOADING BAR
 * --------------------------------------------------------------------
 */

    .loading-bar {
        position: fixed;
        top: 0;
        left: 0;
        height: 3px;
        width: 0;
        opacity: 0;
        background: var(--accent-color);
        transition: width 0.25s ease-in-out;
        z-index: 50;
        pointer-events: none;
    }

    .loading-bar.is-visible {
        opacity: 1;
    }

    /**
 * --------------------------------------------------------------------
 * EMPTY STATE
 * --------------------------------------------------------------------
 */

    .empty-state {
        margin: 100px 0;
        text-align: center;
    }

    .empty-state--extra-tight {
        margin: 30px 0;
    }

    .empty-state--tight {
        margin: 40px 0;
    }

    .empty-state__heading {
        margin-bottom: 15px;
    }

    .empty-state__text {
        margin-bottom: 32px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 15px));
    }

    .empty-state__quick-form {
        max-width: 410px;
        margin: 40px auto 25px auto;
    }

    .empty-state__button-container {
        margin-top: 16px;
    }

    .empty-state__button {
        min-width: 230px;
    }

    .empty-state__icon {
        position: relative;
        display: inline-block;
        margin-bottom: 6px;
    }

    .empty-state__icon .icon--package {
        width: 46px;
        height: 46px;
    }

    .empty-state__icon .icon--address {
        width: 46px;
        height: 45px;
    }

    .empty-state__icon-description {
        margin-bottom: 30px;
    }

    .empty-state__count {
        position: absolute;
        top: 2px;
        right: -9px;
        height: 20px;
        width: 20px;
        line-height: 20px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
        font-weight: var(--text-font-bolder-weight);
        text-align: center;
        background: var(--accent-color);
        color: var(--header-text-color);
        border-radius: 100%;
    }

    @media screen and (min-width: 641px) {
        .empty-state {
            margin: 170px 0;
        }

        .empty-state--extra-tight {
            margin: 40px 0;
        }

        .empty-state--tight {
            margin: 105px 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * PAYMENT METHODS
 * --------------------------------------------------------------------
 */

    .payment-list {
        display: flex;
        flex-wrap: wrap;
        margin: -4px;
    }

    .payment-list__item {
        width: 48px;
        height: 34px;
        margin: 4px;
    }

    .payment-list__notice {
        margin-top: 18px;
    }

    /* Centered variation */
    .payment-list--centered {
        justify-content: center;
    }

    /**
 * --------------------------------------------------------------------
 * LAYOUT
 *
 * Layout component can be used to create a two columns layout on laptop.
 * You can also create a smaller section by adding the "secondary" class
 * to a given layout section
 * --------------------------------------------------------------------
 */

    .layout {
        margin-bottom: 70px;
    }

    .layout .layout {
        margin-top: 18px;
        margin-bottom: 0;
        /* nested layouts don't have margin bottom */
    }

    .layout__section {
        margin-bottom: 18px;
    }

    .layout .card:last-child {
        margin-bottom: 0;
    }

    @media screen and (max-width: 999px) {
        .layout--reverse {
            display: flex;
            flex-direction: column-reverse;
        }
    }

    @media screen and (min-width: 641px) {
        .layout {
            margin-bottom: 100px;
        }

        .layout .layout {
            margin-top: 30px;
        }
    }

    @media screen and (min-width: 1000px) {
        .layout {
            display: flex;
            margin-left: -15px;
            margin-right: -15px;
        }

        .layout--pad {
            padding-top: 25px;
        }

        .layout__section {
            margin: 0 15px;
            /* We need to use the individual properties instead of short hand due to a bug in IE11 */
            flex-grow: 1;
            flex-shrink: 0;
            flex-basis: 0;
        }

        .layout__section:only-child {
            max-width: 680px;
            margin-left: auto;
            margin-right: auto;
        }

        .layout__section--secondary {
            flex: none;
            width: 260px;
        }

        .layout__section--large-secondary {
            flex: none;
            width: 320px;
        }
    }

    @media screen and (min-width: 1280px) {
        .layout__section--secondary {
            width: 288px;
        }

        .layout__section--large-secondary {
            width: 365px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * MODAL
 * --------------------------------------------------------------------
 */

    .modal {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        margin: 0 auto;
        z-index: 10;
        visibility: hidden;
        pointer-events: none;
        opacity: 0;
        transition: opacity 0.2s ease-in-out, visibility 0.2s ease-in-out;
    }

    .modal::before {
        position: fixed;
        content: "";
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.35);
        pointer-events: none;
    }

    .modal[aria-hidden=false] {
        visibility: visible;
        opacity: 1;
        pointer-events: auto;
    }

    .modal[aria-hidden=false] .modal__dialog {
        transform: scale(1);
        transition: transform 0.4s cubic-bezier(0.18, 1.25, 0.4, 1), visibility 0.4s linear;
    }

    .modal__dialog {
        position: absolute;
        width: 100%;
        height: 100%;
        max-height: 100vh;
        background: var(--secondary-background);
        box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
        overflow: auto;
        -webkit-overflow-scrolling: touch;
        transform: scale(0.9);
        transition: transform 0.25s ease-in-out, visibility 0.25s ease-in-out;
    }

    .modal__loader {
        display: none;
        padding: 60px 0;
        text-align: center;
    }

    .modal__loader .icon--search-loader {
        width: 35px;
        height: 35px;
        color: var(--accent-color);
    }

    .modal__header {
        position: -webkit-sticky;
        position: sticky;
        top: 0;
        display: flex;
        align-items: center;
        justify-content: space-between;
        border-bottom: 1px solid var(--border-color);
        background: var(--secondary-background);
        z-index: 1;
    }

    .modal__header,
    .modal__content {
        padding: 20px;
    }

    .modal__header+.modal__content {
        padding-top: 30px;
    }

    .modal__title {
        margin-bottom: 0;
        text-align: center;
    }

    .modal__description {
        display: block;
        margin-bottom: 30px;
        text-align: center;
    }

    .modal__close {
        color: var(--heading-color);
        z-index: 1;
    }

    .modal__close svg {
        display: block;
        width: 20px;
        height: 20px;
    }

    /* Ugly fix for border radius */
    .modal .card {
        background: none;
    }

    /* Loading state */
    .modal.is-loading .modal__loader {
        display: block;
    }

    .modal.is-loading .modal__inner {
        display: none;
    }

    @media screen and (max-width: 640px) {
        .modal__content--ios-push {
            padding-bottom: 45px;
            /* This allows to take into account the toolbar height of iOS to avoid annoying double click */
        }
    }

    @media screen and (min-width: 641px) {
        .modal {
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .modal__dialog {
            width: 580px;
            height: auto;
            max-height: calc(100% - 80px);
            border-radius: 3px;
        }

        .modal__dialog--stretch {
            width: calc(100% - 80px);
            margin-left: auto;
            margin-right: auto;
            max-width: 1200px;
        }

        .modal__header,
        .modal__content {
            padding: 30px;
        }

        .modal__header:not(.modal__header--bordered) {
            position: relative;
            display: block;
            padding-bottom: 0;
            text-align: center;
            border-bottom: none;
        }

        .modal__header--bordered {
            padding-top: 20px;
            padding-bottom: 20px;
        }

        .modal__close {
            position: absolute;
            right: 28px;
            top: 28px;
        }

        .modal__description {
            margin-top: -18px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * ICON STATE
 *
 * This allows to switch between two icons depending on an expanded status
 * --------------------------------------------------------------------
 */

    .icon-state {
        position: relative;
        vertical-align: middle;
    }

    .icon-state .icon-state__primary,
    .icon-state .icon-state__secondary {
        display: block;
        transition: opacity 0.35s ease-in-out, transform 0.35s ease-in-out;
    }

    .icon-state .icon-state__secondary {
        position: absolute;
        top: 50%;
        left: 0;
        opacity: 0;
        transform: translateY(-50%) scale(0.3);
    }

    .icon-state[aria-expanded=true] .icon-state__primary {
        opacity: 0;
        transform: scale(0.3);
    }

    .icon-state[aria-expanded=true] .icon-state__secondary {
        opacity: 1;
        transform: translateY(-50%) scale(1);
    }

    /**
 * ----------------------------------------------------------------------------
 * TOOLTIP
 * ----------------------------------------------------------------------------
 */

    @media (-moz-touch-enabled: 0),
    (hover: hover) {
        [data-tooltip] {
            position: relative;
        }

        [data-tooltip]::before {
            position: absolute;
            content: attr(data-tooltip);
            bottom: calc(100% + 3px);
            left: 50%;
            padding: 2px 11px;
            white-space: nowrap;
            background: var(--accent-color);
            color: var(--secondary-background);
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
            pointer-events: none;
            visibility: hidden;
            opacity: 0;
            border-radius: 3px;
            box-shadow: 0 1px rgba(0, 0, 0, 0.065);
            transition: visibility 0.2s ease-in-out, opacity 0.2s ease-in-out;
            z-index: 1;
            transform: translateX(-50%);
        }

        [data-tooltip]::after {
            position: absolute;
            content: "";
            left: calc(50% - 7px);
            bottom: calc(100% - 2px);
            width: 0;
            height: 0;
            border-width: 6px;
            border-style: solid;
            border-color: transparent transparent var(--accent-color) var(--accent-color);
            visibility: hidden;
            z-index: 1;
            opacity: 0;
            transition: visibility 0.2s ease-in-out, opacity 0.2s ease-in-out;
            transform: rotate(-45deg);
            box-shadow: -1px 1px 1px 0 rgba(0, 0, 0, 0.1);
        }

        [data-tooltip]:hover::before,
        [data-tooltip]:hover::after {
            opacity: 1;
            visibility: visible;
        }

        [data-tooltip-position=bottom-left]::before {
            top: calc(100% + 4px);
            bottom: auto;
            left: auto;
            right: -6px;
            transform: none;
        }

        [data-tooltip-position=bottom-left]::after {
            top: calc(100% - 1px);
            transform: rotate(135deg);
            left: calc(50% - 6px);
        }
    }

    /**
 * --------------------------------------------------------------------
 * QUANTITY SELECTOR
 * --------------------------------------------------------------------
 */

    .quantity-selector {
        display: inline-flex;
        align-items: center;
        height: 38px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 15px));

        border-radius: 3px;
        box-shadow: 0 1px 1px rgba(var(--border-color-rgb), 0.2);
        vertical-align: middle;
    }

    .quantity-selector svg:hover {
        opacity: 1;
    }

    .quantity-selector .icon--minus {
        width: 10px;
        height: 2px;
    }

    .quantity-selector .icon--plus {
        width: 10px;
        height: 10px;
    }

    .quantity-selector__button {
        display: flex;
        align-items: center;
        padding: 0 12px;
        color: rgba(var(--text-color-rgb), 0.6);
        height: 100%;
        transition: color 0.2s ease-in-out;
        touch-action: manipulation;
    }

    .quantity-selector__button:not([disabled]):hover {
        color: var(--heading-color);
    }

    .quantity-selector__value {
        -webkit-appearance: none;
        -moz-appearance: none;
        appearance: none;
        padding: 0 5px;
        min-width: 32px;
        text-align: center;
        border: none;
        background: transparent;
    }

    .quantity-selector__value:focus {
        outline: none;
    }

    /* The "product" variation is a bigger selector used on product pages only */

    .quantity-selector--product {
        height: 44px;
    }

    .quantity-selector--product .quantity-selector__button {
        padding: 0 16px;
    }

    .quantity-selector--product .quantity-selector__value {
        height: 100%;
        min-width: 64px;
        border-left: 1px solid var(--border-color);
        border-right: 1px solid var(--border-color);
        box-shadow: 0 1px rgba(var(--border-color-rgb), 0.4) inset;
        color: var(--heading-color);
        margin: 0 5px;
    }

    /**
 * --------------------------------------------------------------------
 * SHIPPING ESTIMATOR
 * --------------------------------------------------------------------
 */

    .shipping-estimator__results {
        margin: 24px 0 2px 0;
        font-size: 1rem;
    }

    .shipping-estimator__results p {
        margin-bottom: 6px;
    }

    .shipping-estimator__results ul {
        color: var(--heading-color);
        font-weight: var(--text-font-bolder-weight);
    }

    /**
 * --------------------------------------------------------------------
 * COOKIE BAR
 * --------------------------------------------------------------------
 */

    .cookie-bar {
        position: fixed;
        bottom: 20px;
        left: 0;
        visibility: hidden;
        opacity: 0;
        transform: translateY(100%);
        width: 100%;
        z-index: 7;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 11px));
        transition: transform 0.35s ease-in-out, opacity 0.35s ease-in-out, visibility 0.35s ease-in-out;
    }

    .cookie-bar[aria-hidden=false] {
        visibility: visible;
        transform: translateY(0);
        opacity: 1;
    }

    .cookie-bar__inner {
        max-width: 960px;
        margin: 0 auto;
        padding: 15px;
        z-index: 4;
        border-radius: 3px;
        background: var(--secondary-background);
        box-shadow: 0 1px 4px 1px rgba(0, 0, 0, 0.1);
    }

    .cookie-bar__text {
        line-height: 1.45;
    }

    .cookie-bar__button {
        margin-top: 12px;
        padding: 0 16px;
        line-height: 30px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 12px));
    }

    @media screen and (min-width: 641px) {
        .cookie-bar {
            bottom: 25px;
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        }

        .cookie-bar__inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 20px 30px 20px 25px;
        }

        .cookie-bar__text {
            line-height: 1.25;
        }

        .cookie-bar__button {
            flex: none;
            margin-left: 25px;
            margin-top: 0;
            padding: 0 18px;
            line-height: 36px;
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        }
    }

    /**
 * --------------------------------------------------------------------
 * CONTACT FORM
 * --------------------------------------------------------------------
 */

    .contact {
        margin-bottom: 40px;
    }

    .contact__store-info {
        margin-top: 50px;
    }

    .contact__store-heading,
    .contact__store-image {
        margin-bottom: 30px;
    }

    @media screen and (min-width: 641px) {
        .contact {
            margin-bottom: 90px;
        }
    }

    @media screen and (min-width: 1000px) {
        .contact__store-info {
            margin-top: 0;
            margin-left: 25px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * PASSWORD PAGE
 * --------------------------------------------------------------------
 */

    .password {
        display: flex;
        align-items: center;
        justify-content: center;
        flex-direction: column;
        height: 100vh;
        padding: 20px 0;
    }

    @supports (--css: variables) {
        .password {
            height: calc(100vh - 0px);
            height: calc(100vh - var(--header-height, 0px));
        }
    }

    .password__content {
        display: flex;
        align-items: center;
        flex: 1 0 auto;
        text-align: center;
    }

    .password__footer {
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 13px));
        text-align: center;
    }

    .password__footer-social {
        display: flex;
        justify-content: center;
        margin-top: 15px;
    }

    .password__social-text {
        margin-right: 20px;
    }

    .password__powered-by a {
        display: inline-block;
        margin-left: 4px;
        vertical-align: bottom;
    }

    .password__powered-by svg {
        width: 98px;
        height: 28px;
    }

    .password__admin-link {
        display: block;
        margin-left: 18px;
    }

    @media screen and (min-width: 1000px) {

        /* On password there is no search bar so we increase the header */
        .template-password .header {
            padding-top: 30px;
            padding-bottom: 30px;
        }

        .password {
            padding: 40px 0;
        }

        .password__footer {
            text-align: left;
        }

        .password__footer--with-social {
            display: flex;
            width: 100%;
            justify-content: space-between;
        }

        .password__admin-link {
            display: inline-block;
        }

        .password__footer-social {
            margin-top: 0;
        }
    }

    /**
 * --------------------------------------------------------------------
 * FAQ
 * --------------------------------------------------------------------
 */

    .faq {
        margin: 40px 0 70px 0;
    }

    .faq__title {
        margin-bottom: 20px;
        text-align: center;
    }

    .faq__item {
        padding: 20px 20px;
        background: var(--secondary-background);
        border-top: 1px solid var(--border-color);
        border-bottom: 1px solid var(--border-color);
    }

    .faq__item+.faq__item {
        border-top: none;
    }

    .faq__question {
        display: flex;
        align-items: center;
        justify-content: space-between;
        width: 100%;
        text-align: left;
    }

    .faq__question .plus-button {
        margin-left: 40px;
    }

    .faq__answer-wrapper {
        overflow: hidden;
        height: 0;
        transition: height 0.2s ease-in-out;
    }

    .faq__answer {
        margin: 10px 30px 0 0;
    }

    .faq__group {
        margin-bottom: 30px;
    }

    .faq__group-title {
        text-align: center;
    }

    .faq__contact-info {
        margin-top: 50px;
    }

    @media screen and (min-width: 641px) {
        .faq {
            margin: 70px 0 115px 0;
        }

        .faq__title {
            margin-bottom: 25px;
            margin-left: 0;
        }

        .faq__item {
            padding: 20px 30px;
            border: 1px solid var(--border-color);
            border-radius: 3px 3px 0 0;
        }

        .faq__item+.faq__item {
            border-radius: 0;
        }

        .faq__item:last-child {
            border-radius: 0 0 3px 3px;
        }
    }

    @media screen and (min-width: 1000px) {
        .faq__group {
            margin-bottom: 0;
        }

        .faq__group+.faq__group {
            margin-top: 50px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * POPUP NEWSLETTER
 * --------------------------------------------------------------------
 */

    .modal--newsletter {
        bottom: 0;
        top: auto;
        height: auto;
    }

    .modal--newsletter .modal__dialog {
        position: relative;
        height: auto;
        padding: 48px 20px 20px 20px;
    }

    .popup-newsletter__title {
        text-align: center;
        margin-bottom: 10px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 20px));
    }

    .popup-newsletter__close {
        position: absolute;
        right: 20px;
        top: 16px;
        color: var(--heading-color);
    }

    .popup-newsletter__close svg {
        width: 15px;
        height: 15px;
    }

    .popup-newsletter__content {
        text-align: center;
    }

    .popup-newsletter__form {
        margin-top: 20px;
    }

    @media screen and (min-width: 641px) {
        .modal--newsletter {
            height: 100%;
        }

        .modal--newsletter .modal__dialog {
            max-width: 540px;
            padding: 64px 80px 80px 80px;
        }

        .popup-newsletter__close {
            position: absolute;
            right: 30px;
            top: 24px;
        }

        .popup-newsletter__close svg {
            width: 20px;
            height: 20px;
        }

        .popup-newsletter__title {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 28px));
        }

        .popup-newsletter__form {
            margin-top: 30px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * EXIT POPUP NEWSLETTER
 * --------------------------------------------------------------------
 */

    .modal--exit-popup {
        bottom: 0;
        top: auto;
        height: auto;
    }

    .modal--exit-popup .modal__dialog {
        position: relative;
        height: auto;
        padding: 48px 20px 20px 20px;
    }

    .exit-popup__title {
        text-align: center;
        margin-bottom: 8px;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 28px));
        line-height: 1.2;
    }

    .exit-popup__subheading {
        text-align: center;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 18px));
    }

    .exit-popup__close {
        position: absolute;
        right: 20px;
        top: 16px;
        color: var(--heading-color);
    }

    .exit-popup__close svg {
        width: 15px;
        height: 15px;
    }

    .exit-popup__form {
        margin-top: 20px;
    }

    .exit-popup__pay-more {
        display: block;
        margin-top: 20px;
        text-align: center;
        margin-left: auto;
        margin-right: auto;
    }

    @media screen and (min-width: 641px) {
        .modal--exit-popup {
            height: 100%;
        }

        .modal--exit-popup .modal__dialog {
            max-width: 540px;
            padding: 95px 80px 30px 80px;
        }

        .exit-popup__close {
            position: absolute;
            right: 30px;
            top: 24px;
        }

        .exit-popup__close svg {
            width: 20px;
            height: 20px;
        }

        .exit-popup__title {
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 48px));
        }

        .exit-popup__form {
            margin-top: 30px;
        }

        .exit-popup__pay-more {
            margin-top: 75px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * DRAWER
 * --------------------------------------------------------------------
 */

    .drawer {
        position: fixed;
        top: 0;
        right: 0;
        height: 100vh;
        width: 100vw;
        z-index: 5;
        visibility: hidden;
        transition: visibility 0.35s linear;
    }

    .drawer::before {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0;
        transition: opacity 0.35s ease-in-out;
        background: #000000;
    }

    .drawer__inner {
        position: absolute;
        right: 0;
        top: 0;
        width: 100%;
        height: 100%;
        max-width: 345px;
        margin-left: auto;
        background: var(--secondary-background);
        transform: translateX(100%);
        transition: transform 0.35s cubic-bezier(0.645, 0.045, 0.355, 1);
    }

    .drawer[aria-hidden=false] {
        visibility: visible;
    }

    .drawer[aria-hidden=false]::before {
        opacity: 0.4;
    }

    .drawer[aria-hidden=false] .drawer__inner {
        transform: translateX(0);
    }

    /**
 * --------------------------------------------------------------------
 * SEARCH RESULTS
 * --------------------------------------------------------------------
 */

    .link-search-results:not(:only-child) {
        margin-top: 40px;
    }

    .link-search-results__list {
        list-style: none;
    }

    .link-search-results__link {
        display: block;
        padding: 8px 20px;
        transition: color 0.15s ease-in-out, background 0.15s ease-in-out;
    }

    .link-search-results__link:hover,
    .link-search-results__link:focus {
        background: var(--accent-background);
        color: var(--accent-color);
        outline: none;
    }

    @media screen and (min-width: 641px) {
        .link-search-results:not(:only-child) {
            margin-top: 60px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * EXPANDABLE CONTENT
 * --------------------------------------------------------------------
 */

    .expandable-content[aria-expanded] {
        position: relative;
        max-height: 320px;
        overflow: hidden;
        transition: 0.2s ease-in-out;
    }

    .expandable-content__toggle {
        position: absolute;
        display: flex;
        align-items: center;
        left: 0;
        bottom: 0;
        width: 100%;
        padding: 16px 20px;
        visibility: hidden;
        opacity: 0;
        color: var(--accent-color);
        text-align: left;
        font-weight: var(--text-font-bolder-weight);
        background: var(--secondary-background);
        z-index: 1;
        transition: opacity 0.1s ease-in-out, visibility 0.1s ease-in-out;
    }

    .expandable-content__toggle::before {
        position: absolute;
        content: "";
        bottom: 100%;
        left: 0;
        width: 100%;
        height: 50px;
        pointer-events: none;
        background: linear-gradient(rgba(var(--secondary-background-rgb), 0), rgba(var(--secondary-background-rgb), 0.4) 15%, var(--secondary-background));
    }

    .expandable-content__toggle-icon {
        position: relative;
        margin-right: 15px;
        width: 10px;
        height: 10px;
        transition: transform 0.2s ease-in-out;
    }

    .expandable-content__toggle-icon::before,
    .expandable-content__toggle-icon::after {
        content: "";
        position: absolute;
        background: currentColor;
        transition: transform 0.2s ease-in-out;
        transform: translate(-50%, -50%);
        top: 50%;
        left: 50%;
    }

    .expandable-content__toggle-icon::before {
        width: 2px;
        height: 10px;
    }

    .expandable-content__toggle-icon::after {
        width: 10px;
        height: 2px;
    }

    .expandable-content--expandable[aria-expanded=true] .expandable-content__toggle-icon {
        transform: rotateZ(90deg);
    }

    .expandable-content--expandable[aria-expanded=true] .expandable-content__toggle-icon::after {
        display: none;
    }

    .expandable-content--expandable .expandable-content__toggle {
        visibility: visible;
        opacity: 1;
    }

    .expandable-content--expandable[aria-expanded=true] .expandable-content__toggle::before {
        height: 0;
    }

    @media (-moz-touch-enabled: 0),
    (hover: hover) {
        .expandable-content[aria-expanded=false] .expandable-content__toggle:hover .expandable-content__toggle-icon {
            transform: rotateZ(45deg);
        }
    }

    @media screen and (min-width: 641px) {
        .expandable-content__toggle {
            padding-left: 30px;
            padding-right: 30px;
        }
    }

    /**
 * --------------------------------------------------------------------
 * MENU (used exclusively in "custom content" section for now)
 * --------------------------------------------------------------------
 */

    .menu-item__title {
        margin-bottom: 0.75em;
    }

    .menu-item__linklist {
        list-style: none;
    }

    .menu-item__link-item {
        padding: 5px 0;
    }

    /**
 * --------------------------------------------------------------------
 * VALUE PICKER
 *
 * This component allows to provide a replacement to dropdown select.
 * On mobile it used by opening a drawer box, while on desktop it looks
 * like a popover
 * --------------------------------------------------------------------
 */
    .value-picker-button svg {
        width: 9px;
        height: 7px;
        margin-left: 10px;
        transition: transform 0.2s ease-in-out;
    }

    .value-picker-button svg path {
        stroke-width: 2.5px;
    }

    .value-picker-button--pill {
        position: relative;
        display: flex;
        justify-content: space-between;
        align-items: center;
        width: 100%;
        padding: 14px 20px;
        text-align: left;
        border-bottom: 1px solid var(--border-color);
        background: var(--secondary-background);
    }

    .value-picker-button--pill svg {
        width: 12px;
        height: 8px;
        transition: transform 0.2s ease-in-out;
    }

    .value-picker-button--pill path {
        stroke-width: 2px;
    }

    .value-picker-button[aria-expanded=true] svg {
        transform: rotateZ(180deg);
    }

    .value-picker {
        position: fixed;
        left: 0;
        bottom: 0;
        width: 100vw;
        height: 100vh;
        z-index: 5;
        font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 16px));
        visibility: hidden;
        transition: visibility 0.35s ease-in-out;
    }

    .value-picker::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        opacity: 0;
        transition: opacity 0.35s ease-in-out;
        background: #000000;
    }

    .value-picker[aria-hidden=false] {
        visibility: visible;
    }

    .value-picker[aria-hidden=false]::before {
        opacity: 0.4;
    }

    .value-picker[aria-hidden=false] .value-picker__inner {
        transform: translateY(0);
    }

    .value-picker .icon--nav-triangle-borderless {
        display: none;
    }

    .value-picker__inner {
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        background: var(--secondary-background);
        transform: translateY(100%);
        transition: visibility 0.2s ease-in-out, transform 0.2s ease-in-out;
    }

    .value-picker__header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 17px 20px 16px 20px;
        border-bottom: 1px solid var(--border-color);
    }

    .value-picker__header .icon--close {
        width: 17px;
        height: 17px;
        color: var(--heading-color);
    }

    .value-picker__title {
        margin: 0;
    }

    .value-picker__close svg {
        display: block;
    }

    .value-picker__choice-list {
        padding: 15px 0;
        max-height: 430px;
        overflow: auto;
        -webkit-overflow-scrolling: touch;
        -ms-scroll-chaining: none;
        overscroll-behavior: none;
        list-style: none;
    }

    .value-picker__choice-item {
        display: block;
        position: relative;
        width: 100%;
        text-align: left;
        padding: 8px 50px 7px 20px;
        /* Designer does not like symmetry, sorry :D */
    }

    .value-picker__choice-item svg {
        position: absolute;
        width: 13px;
        height: 11px;
        right: 20px;
        top: 17px;
        transform: scale(0);
        transition: transform 0.2s ease-in-out;
    }

    .value-picker__choice-item.is-selected {
        color: var(--accent-color);
        font-weight: var(--text-font-bolder-weight);
    }

    .value-picker__choice-item.is-selected svg {
        transform: scale(1);
    }

    /* On tablet and higher, the selector will look like a popover */
    @media screen and (min-width: 641px) {

        /* This is the wrapper class on which elements are positioned relatively on desktop */
        .value-picker-wrapper {
            position: relative;
        }

        .value-picker {
            position: absolute;
            width: auto;
            height: auto;
            top: calc(100% + 10px);
            left: auto;
            right: -25px;
            bottom: auto;
            min-width: 160px;
            box-shadow: 0 1px 5px 2px rgba(0, 0, 0, 0.1);
            visibility: hidden;
            opacity: 0;
            transform: scale(0.9);
            background: var(--secondary-background);
            color: var(--text-color);
            z-index: 4;
            cursor: auto;
            border-radius: 3px;
            transition: opacity 0.25s ease-in-out, transform 0.25s ease-in-out, visibility 0.25s ease-in-out;
            will-change: transform;
        }

        .value-picker::before {
            display: none;
        }

        .value-picker[data-picker-position=top] {
            top: auto;
            bottom: calc(100% + 10px);
        }

        .value-picker[aria-hidden=false] {
            visibility: visible;
            opacity: 1;
            transform: scale(1.001);
            transition: opacity 0.4s cubic-bezier(0, 1, 0.4, 1), transform 0.4s cubic-bezier(0.18, 1.25, 0.4, 1), visibility 0.4s linear;
        }

        .value-picker .icon--nav-triangle-borderless {
            display: block;
            position: absolute;
            bottom: 100%;
            right: 20px;
            width: 18px;
            height: 8px;
            z-index: 2;
            filter: drop-shadow(0 -2px 2px rgba(0, 0, 0, 0.12));
        }

        .value-picker[data-picker-position=top] .icon--nav-triangle-borderless {
            bottom: auto;
            top: 100%;
            transform: rotateZ(180deg);
        }

        .value-picker__inner {
            position: relative;
            width: auto;
            transform: none !important;
            transition: none;
            border-radius: 3px;
        }

        .value-picker__header {
            display: none;
            /* Because of popover the context is clear and does not need header */
        }

        .value-picker__choice-list {
            padding: 15px 0;
            max-height: none;
            white-space: nowrap;
            font-size: calc(var(--base-text-font-size) - (var(--default-text-font-size) - 15px));
        }

        .value-picker__choice-item {
            display: block;
            padding: 2px 25px;
            cursor: pointer;
            transition: color 0.15s ease-in-out, background 0.15s ease-in-out;
        }

        .value-picker__choice-item.is-selected,
        .value-picker__choice-item:hover {
            background: var(--accent-background);
            color: var(--accent-color);
            font-weight: normal;
        }

        .value-picker__choice-item.is-selected svg,
        .value-picker__choice-item:hover svg {
            display: none;
        }

        /* Small variation */
        .value-picker--small {
            min-width: 105px;
            right: -2px;
        }

        .value-picker--small .value-picker__choice-list {
            padding: 10px 0;
            font-size: 0.85rem;
        }

        .value-picker--small .value-picker__choice-item {
            padding: 2px 18px;
        }

        .value-picker--small .icon--nav-triangle-borderless {
            right: 11px;
        }

        /* Auto variation */
        .value-picker--auto {
            min-width: 0;
        }
    }

    /*================ Default carousel ================*/
    .carousel {
        opacity: 0;
        visibility: hidden;
        transition: opacity 1s ease;
        -webkit-transition: opacity 1s ease;
    }

    .carousel.flickity-enabled {
        visibility: visible;
        opacity: 1;
        transition: opacity 1s ease;
        -webkit-transition: opacity 1s ease;
    }

    .carousel-cell {
        width: 100%;
        margin-right: 10px;
    }